export default [{"id":"1365","jozz":"11","page":"208","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"3","line_end":"3","aya_no":"1","aya_text":"الٓرۚ تِلۡكَ ءَايَٰتُ ٱلۡكِتَٰبِ ٱلۡحَكِيمِ","aya_text_emlaey":"الر تلك آيات الكتاب الحكيم","aya_tafseer":"[1] الٓرۚ سبق الكلام على الحروف المقطَّعة في أول سورة البقرة.هذه آيات الكتاب المحكم الذي أحكمه الله وبيَّنه لعباده."},{"id":"1366","jozz":"11","page":"208","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"3","line_end":"6","aya_no":"2","aya_text":"أَكَانَ لِلنَّاسِ عَجَبًا أَنۡ أَوۡحَيۡنَآ إِلَىٰ رَجُلٖ مِّنۡهُمۡ أَنۡ أَنذِرِ ٱلنَّاسَ وَبَشِّرِ ٱلَّذِينَ ءَامَنُوٓاْ أَنَّ لَهُمۡ قَدَمَ صِدۡقٍ عِندَ رَبِّهِمۡۗ قَالَ ٱلۡكَٰفِرُونَ إِنَّ هَٰذَا لَسَٰحِرٞ مُّبِينٌ","aya_text_emlaey":"أكان للناس عجبا أن أوحينا إلى رجل منهم أن أنذر الناس وبشر الذين آمنوا أن لهم قدم صدق عند ربهم قال الكافرون إن هذا لساحر مبين","aya_tafseer":"[2] أكان أمراً عجباً للناس إنزالنا الوحي بالقرآن على رجل منهم ينذرهم عقاب الله، ويبشِّر الذين آمنوا بالله ورسله أن لهم أجراً حسناً بما قدَّموا من صالح الأعمال؟ فلما أتاهم رسول الله -صلى الله عليه وسلم- بوحي الله وتلاه عليهم، قال المنكرون: إنَّ محمداً ساحر، وما جاء به سحر ظاهر البطلان."},{"id":"1367","jozz":"11","page":"208","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"6","line_end":"8","aya_no":"3","aya_text":"إِنَّ رَبَّكُمُ ٱللَّهُ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ فِي سِتَّةِ أَيَّامٖ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ يُدَبِّرُ ٱلۡأَمۡرَۖ مَا مِن شَفِيعٍ إِلَّا مِنۢ بَعۡدِ إِذۡنِهِۦۚ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡ فَٱعۡبُدُوهُۚ أَفَلَا تَذَكَّرُونَ","aya_text_emlaey":"إن ربكم الله الذي خلق السموات والأرض في ستة أيام ثم استوى على العرش يدبر الأمر ما من شفيع إلا من بعد إذنه ذلكم الله ربكم فاعبدوه أفلا تذكرون","aya_tafseer":"[3] إن ربكم الله الذي أوجد السموات والأرض في ستة أيام، ثم استوى -أي: علا وارتفع- على العرش استواء يليق بجلاله وعظمته، يدبر أمور خلقه، لا يضادُّه في قضائه أحد، ولا يشفع عنده شافع يوم القيامة إلا من بعد أن يأذن له بالشفاعة، فاعبدوا الله ربكم المتصف بهذه الصفات، وأخلصوا له العبادة. أفلا تتعظون وتعتبرون بهذه الآيات والحجج؟"},{"id":"1368","jozz":"11","page":"208","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"9","line_end":"11","aya_no":"4","aya_text":"إِلَيۡهِ مَرۡجِعُكُمۡ جَمِيعٗاۖ وَعۡدَ ٱللَّهِ حَقًّاۚ إِنَّهُۥ يَبۡدَؤُاْ ٱلۡخَلۡقَ ثُمَّ يُعِيدُهُۥ لِيَجۡزِيَ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ بِٱلۡقِسۡطِۚ وَٱلَّذِينَ كَفَرُواْ لَهُمۡ شَرَابٞ مِّنۡ حَمِيمٖ وَعَذَابٌ أَلِيمُۢ بِمَا كَانُواْ يَكۡفُرُونَ","aya_text_emlaey":"إليه مرجعكم جميعا وعد الله حقا إنه يبدأ الخلق ثم يعيده ليجزي الذين آمنوا وعملوا الصالحات بالقسط والذين كفروا لهم شراب من حميم وعذاب أليم بما كانوا يكفرون","aya_tafseer":"[4] إلى ربكم معادكم يوم القيامة جميعاً، وهذا وعد الله الحق، هو الذي يبدأ إيجاد الخلق ثم يعيده بعد الموت، فيوجده حيّاً كهيئته الأولى؛ ليجزي مَن صَدَّق الله ورسوله، وعمل الأعمال الحسنة أحسن الجزاء بالعدل. والذين جحدوا وحدانية الله ورسالة رسوله لهم شراب من ماء شديد الحرارة يشوي الوجوه ويقطِّع الأمعاء، ولهم عذاب موجع بسبب كفرهم وضلالهم."},{"id":"1369","jozz":"11","page":"208","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"12","line_end":"14","aya_no":"5","aya_text":"هُوَ ٱلَّذِي جَعَلَ ٱلشَّمۡسَ ضِيَآءٗ وَٱلۡقَمَرَ نُورٗا وَقَدَّرَهُۥ مَنَازِلَ لِتَعۡلَمُواْ عَدَدَ ٱلسِّنِينَ وَٱلۡحِسَابَۚ مَا خَلَقَ ٱللَّهُ ذَٰلِكَ إِلَّا بِٱلۡحَقِّۚ يُفَصِّلُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَعۡلَمُونَ","aya_text_emlaey":"هو الذي جعل الشمس ضياء والقمر نورا وقدره منازل لتعلموا عدد السنين والحساب ما خلق الله ذلك إلا بالحق يفصل الآيات لقوم يعلمون","aya_tafseer":"[5] الله هو الذي جعل الشمس ضياء، وجعل القمر نوراً، وقدَّر القمر منازل، فبالشمس تعرف الأيام، وبالقمر تعرف الشهور والأعوام، ما خلق الله تعالى الشمس والقمر إلا لحكمة عظيمة، ودلالة على كمال قدرة الله وعلمه، يبيِّن الحجج والأدلة لقوم يعلمون الحكمة في إبداع الخلق."},{"id":"1370","jozz":"11","page":"208","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"14","line_end":"15","aya_no":"6","aya_text":"إِنَّ فِي ٱخۡتِلَٰفِ ٱلَّيۡلِ وَٱلنَّهَارِ وَمَا خَلَقَ ٱللَّهُ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ لَأٓيَٰتٖ لِّقَوۡمٖ يَتَّقُونَ","aya_text_emlaey":"إن في اختلاف الليل والنهار وما خلق الله في السموات والأرض لآيات لقوم يتقون","aya_tafseer":"[6] إن في تعاقب الليل والنهار وما خلق الله في السموات والأرض من عجائب الخلق وما فيهما من إبداع ونظام، لأدلةً وحججاً واضحة لقوم يخشون عقاب الله وسخطه وعذابه."},{"id":"1371","jozz":"11","page":"209","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"1","line_end":"2","aya_no":"7","aya_text":"إِنَّ ٱلَّذِينَ لَا يَرۡجُونَ لِقَآءَنَا وَرَضُواْ بِٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَٱطۡمَأَنُّواْ بِهَا وَٱلَّذِينَ هُمۡ عَنۡ ءَايَٰتِنَا غَٰفِلُونَ","aya_text_emlaey":"إن الذين لا يرجون لقاءنا ورضوا بالحياة الدنيا واطمأنوا بها والذين هم عن آياتنا غافلون","aya_tafseer":"[7] إن الذين لا يطمعون في لقائنا في الآخرة للحساب، وما يتلوه من الجزاء على الأعمال لإنكارهم البعث، ورضوا بالحياة الدنيا عوضاً عن الآخرة، وركنوا إليها، والذين هم عن آياتنا الكونية والشرعية ساهون."},{"id":"1372","jozz":"11","page":"209","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"2","line_end":"3","aya_no":"8","aya_text":"أُوْلَٰٓئِكَ مَأۡوَىٰهُمُ ٱلنَّارُ بِمَا كَانُواْ يَكۡسِبُونَ","aya_text_emlaey":"أولئك مأواهم النار بما كانوا يكسبون","aya_tafseer":"[8] أولئك مقرُّهم نار جهنم في الآخرة؛ جزاء بما كانوا يكسبون في دنياهم من الآثام والخطايا."},{"id":"1373","jozz":"11","page":"209","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"3","line_end":"5","aya_no":"9","aya_text":"إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ يَهۡدِيهِمۡ رَبُّهُم بِإِيمَٰنِهِمۡۖ تَجۡرِي مِن تَحۡتِهِمُ ٱلۡأَنۡهَٰرُ فِي جَنَّٰتِ ٱلنَّعِيمِ","aya_text_emlaey":"إن الذين آمنوا وعملوا الصالحات يهديهم ربهم بإيمانهم تجري من تحتهم الأنهار في جنات النعيم","aya_tafseer":"[9] إن الذين آمنوا بالله ورسوله وعملوا الصالحات يدلُّهم ربهم إلى طريق الجنة، ويوفقهم إلى العمل الموصل إليه؛ بسبب إيمانهم، ثم يثيبهم بدخول الجنة وإحلال رضوانه عليهم، تجري مِن تحت غرفهم ومنازلهم الأنهار في جنات النعيم."},{"id":"1374","jozz":"11","page":"209","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"5","line_end":"7","aya_no":"10","aya_text":"دَعۡوَىٰهُمۡ فِيهَا سُبۡحَٰنَكَ ٱللَّهُمَّ وَتَحِيَّتُهُمۡ فِيهَا سَلَٰمٞۚ وَءَاخِرُ دَعۡوَىٰهُمۡ أَنِ ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ","aya_text_emlaey":"دعواهم فيها سبحانك اللهم وتحيتهم فيها سلام وآخر دعواهم أن الحمد لله رب العالمين","aya_tafseer":"[10] دعاؤهم في الجنة التسبيح (سبحانك اللهم)، وتحية الله وملائكته لهم، وتحية بعضهم بعضاً في الجنة (سلام)، وآخر دعائهم قولهم: «الحمد لله رب العالمين» أي: الشكر والثناء لله خالق المخلوقات ومربِّيها بنعمه."},{"id":"1375","jozz":"11","page":"209","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"7","line_end":"9","aya_no":"11","aya_text":"۞ وَلَوۡ يُعَجِّلُ ٱللَّهُ لِلنَّاسِ ٱلشَّرَّ ٱسۡتِعۡجَالَهُم بِٱلۡخَيۡرِ لَقُضِيَ إِلَيۡهِمۡ أَجَلُهُمۡۖ فَنَذَرُ ٱلَّذِينَ لَا يَرۡجُونَ لِقَآءَنَا فِي طُغۡيَٰنِهِمۡ يَعۡمَهُونَ","aya_text_emlaey":"ولو يعجل الله للناس الشر استعجالهم بالخير لقضي إليهم أجلهم فنذر الذين لا يرجون لقاءنا في طغيانهم يعمهون","aya_tafseer":"[11] ولو يعجِّل الله للناس إجابة دعائهم في الشر كاستعجاله لهم في الخير بالإجابة لهلكوا، فنترك الذين لا يخافون عقابنا، ولا يوقنون بالبعث والنشور في تمرُّدهم وعتوِّهم، يترددون حائرين."},{"id":"1376","jozz":"11","page":"209","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"9","line_end":"12","aya_no":"12","aya_text":"وَإِذَا مَسَّ ٱلۡإِنسَٰنَ ٱلضُّرُّ دَعَانَا لِجَنۢبِهِۦٓ أَوۡ قَاعِدًا أَوۡ قَآئِمٗا فَلَمَّا كَشَفۡنَا عَنۡهُ ضُرَّهُۥ مَرَّ كَأَن لَّمۡ يَدۡعُنَآ إِلَىٰ ضُرّٖ مَّسَّهُۥۚ كَذَٰلِكَ زُيِّنَ لِلۡمُسۡرِفِينَ مَا كَانُواْ يَعۡمَلُونَ","aya_text_emlaey":"وإذا مس الإنسان الضر دعانا لجنبه أو قاعدا أو قائما فلما كشفنا عنه ضره مر كأن لم يدعنا إلى ضر مسه كذلك زين للمسرفين ما كانوا يعملون","aya_tafseer":"[12] وإذا أصاب الإنسانَ الشدةُ استغاث بنا في كشف ذلك عنه، مضطجعاً لجنبه أو قاعداً أو قائماً، على حسب الحال التي يكون بها عند نزول ذلك الضرِّ به. فلما كشفنا عنه الشدة التي أصابته استمرَّ على طريقته الأولى قبل أن يصيبه الضر، ونسي ما كان فيه من الشدة والبلاء، وترك الشكر لربه الذي فرَّج عنه ما كان قد نزل به من البلاء، كما زُيِّن لهذا الإنسان استمراره على جحوده وعناده بعد كشف الله عنه ما كان فيه من الضر، زُيِّن للذين أسرفوا في الكذب على الله وعلى أنبيائه ما كانوا يعملون من معاصي الله والشرك به."},{"id":"1377","jozz":"11","page":"209","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"12","line_end":"14","aya_no":"13","aya_text":"وَلَقَدۡ أَهۡلَكۡنَا ٱلۡقُرُونَ مِن قَبۡلِكُمۡ لَمَّا ظَلَمُواْ وَجَآءَتۡهُمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِ وَمَا كَانُواْ لِيُؤۡمِنُواْۚ كَذَٰلِكَ نَجۡزِي ٱلۡقَوۡمَ ٱلۡمُجۡرِمِينَ","aya_text_emlaey":"ولقد أهلكنا القرون من قبلكم لما ظلموا وجاءتهم رسلهم بالبينات وما كانوا ليؤمنوا كذلك نجزي القوم المجرمين","aya_tafseer":"[13] ولقد أهلكنا الأمم التي كذَّبت رسل الله من قبلكم -أيها المشركون بربهم- لمَّا أشركوا، وجاءتهم رسلهم من عند الله بالمعجزات الواضحات والحجج التي تبين صدق مَن جاء بها، فلم تكن هذه الأمم التي أهلكناها لتصدق رسلها وتنقاد لها، فاستحقوا الهلاك، مثل ذلك الإهلاك نجزي كل مجرم متجاوز حدود الله."},{"id":"1378","jozz":"11","page":"209","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"14","line_end":"15","aya_no":"14","aya_text":"ثُمَّ جَعَلۡنَٰكُمۡ خَلَٰٓئِفَ فِي ٱلۡأَرۡضِ مِنۢ بَعۡدِهِمۡ لِنَنظُرَ كَيۡفَ تَعۡمَلُونَ","aya_text_emlaey":"ثم جعلناكم خلائف في الأرض من بعدهم لننظر كيف تعملون","aya_tafseer":"[14] ثم جعلناكم -أيها الناس- خَلَفاً في الأرض من بعد القرون المُهْلَكة؛ لننظر كيف تعملون: أخيراً أم شراً، فنجازيكم بذلك حسب عملكم."},{"id":"1379","jozz":"11","page":"210","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"1","line_end":"4","aya_no":"15","aya_text":"وَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَاتُنَا بَيِّنَٰتٖ قَالَ ٱلَّذِينَ لَا يَرۡجُونَ لِقَآءَنَا ٱئۡتِ بِقُرۡءَانٍ غَيۡرِ هَٰذَآ أَوۡ بَدِّلۡهُۚ قُلۡ مَا يَكُونُ لِيٓ أَنۡ أُبَدِّلَهُۥ مِن تِلۡقَآيِٕ نَفۡسِيٓۖ إِنۡ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَيَّۖ إِنِّيٓ أَخَافُ إِنۡ عَصَيۡتُ رَبِّي عَذَابَ يَوۡمٍ عَظِيمٖ","aya_text_emlaey":"وإذا تتلى عليهم آياتنا بينات قال الذين لا يرجون لقاءنا ائت بقرآن غير هذا أو بدله قل ما يكون لي أن أبدله من تلقاء نفسي إن أتبع إلا ما يوحى إلي إني أخاف إن عصيت ربي عذاب يوم عظيم","aya_tafseer":"[15] وإذا تتلى على المشركين آيات الله التي أنزلناها إليك -أيها الرسول- واضحات، قال الذين لا يخافون الحساب، ولا يرجون الثواب، ولا يؤمنون بيوم البعث والنشور: ائت بقرآن غير هذا، أو بدِّل هذا القرآن: بأن تجعل الحلال حراماً، والحرام حلالاً، والوعد وعيداً، والوعيد وعداً، وأن تُسْقط ما فيه من عيب آلهتنا وتسفيه أحلامنا، قل لهم -أيها الرسول-: إن ذلك ليس إليَّ، وإنما أتبع في كل ما آمركم به وأنهاكم عنه ما ينزله عليَّ ربي ويأمرني به، إني أخشى من الله -إن خالفت أمره-عذاب يوم عظيم وهو يوم القيامة."},{"id":"1380","jozz":"11","page":"210","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"4","line_end":"6","aya_no":"16","aya_text":"قُل لَّوۡ شَآءَ ٱللَّهُ مَا تَلَوۡتُهُۥ عَلَيۡكُمۡ وَلَآ أَدۡرَىٰكُم بِهِۦۖ فَقَدۡ لَبِثۡتُ فِيكُمۡ عُمُرٗا مِّن قَبۡلِهِۦٓۚ أَفَلَا تَعۡقِلُونَ","aya_text_emlaey":"قل لو شاء الله ما تلوته عليكم ولا أدراكم به فقد لبثت فيكم عمرا من قبله أفلا تعقلون","aya_tafseer":"[16] قل لهم -أيها الرسول-: لو شاء الله ما تلوت هذا القرآن عليكم، ولا أعلمكم الله به، فاعلموا أنه الحق من الله، فإنكم تعلمون أنني مكثت فيكم زمناً طويلاً من قبل أن يوحيه إليَّ ربي، ومن قبل أن أتلوه عليكم، أفلا تستعملون عقولكم بالتدبر والتفكر؟"},{"id":"1381","jozz":"11","page":"210","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"7","line_end":"8","aya_no":"17","aya_text":"فَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ كَذَّبَ بِـَٔايَٰتِهِۦٓۚ إِنَّهُۥ لَا يُفۡلِحُ ٱلۡمُجۡرِمُونَ","aya_text_emlaey":"فمن أظلم ممن افترى على الله كذبا أو كذب بآياته إنه لا يفلح المجرمون","aya_tafseer":"[17] لا أحد أشد ظلماً ممن اختلق على الله الكذب أو كذَّب بآياته، إنه لا ينجح مَن كذَّب بأنبياء الله ورسلِه، ولا ينالون الفلاح."},{"id":"1382","jozz":"11","page":"210","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"8","line_end":"11","aya_no":"18","aya_text":"وَيَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَضُرُّهُمۡ وَلَا يَنفَعُهُمۡ وَيَقُولُونَ هَٰٓؤُلَآءِ شُفَعَٰٓؤُنَا عِندَ ٱللَّهِۚ قُلۡ أَتُنَبِّـُٔونَ ٱللَّهَ بِمَا لَا يَعۡلَمُ فِي ٱلسَّمَٰوَٰتِ وَلَا فِي ٱلۡأَرۡضِۚ سُبۡحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشۡرِكُونَ","aya_text_emlaey":"ويعبدون من دون الله ما لا يضرهم ولا ينفعهم ويقولون هؤلاء شفعاؤنا عند الله قل أتنبئون الله بما لا يعلم في السموات ولا في الأرض سبحانه وتعالى عما يشركون","aya_tafseer":"[18] ويعبد هؤلاء المشركون من دون الله ما لا يضرهم شيئاً، ولا ينفعهم في الدنيا والآخرة، ويقولون: إنما نعبدهم ليشفعوا لنا عند الله، قل لهم -أيها الرسول-: أتخبرون الله تعالى بشيء لا يعلمه مِن أمر هؤلاء الشفعاء في السموات أو في الأرض؟ فإنه لو كان فيهما شفعاء يشفعون لكم عنده لكان أعلم بهم منكم، فالله تعالى منزَّه عما يفعله هؤلاء المشركون من إشراكهم في عبادته ما لا يضر ولا ينفع."},{"id":"1383","jozz":"11","page":"210","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"11","line_end":"13","aya_no":"19","aya_text":"وَمَا كَانَ ٱلنَّاسُ إِلَّآ أُمَّةٗ وَٰحِدَةٗ فَٱخۡتَلَفُواْۚ وَلَوۡلَا كَلِمَةٞ سَبَقَتۡ مِن رَّبِّكَ لَقُضِيَ بَيۡنَهُمۡ فِيمَا فِيهِ يَخۡتَلِفُونَ","aya_text_emlaey":"وما كان الناس إلا أمة واحدة فاختلفوا ولولا كلمة سبقت من ربك لقضي بينهم فيما فيه يختلفون","aya_tafseer":"[19] كان الناس على دين واحد وهو الإسلام، ثم اختلفوا بعد ذلك، فكفر بعضهم، وثبت بعضهم على الحق. ولولا كلمة سبقت من الله بإمهال العاصين وعدم معاجلتهم بذنوبهم لقُضِيَ بينهم: بأن يُهْلك أهل الباطل منهم، وينجي أهل الحق."},{"id":"1384","jozz":"11","page":"210","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"14","line_end":"15","aya_no":"20","aya_text":"وَيَقُولُونَ لَوۡلَآ أُنزِلَ عَلَيۡهِ ءَايَةٞ مِّن رَّبِّهِۦۖ فَقُلۡ إِنَّمَا ٱلۡغَيۡبُ لِلَّهِ فَٱنتَظِرُوٓاْ إِنِّي مَعَكُم مِّنَ ٱلۡمُنتَظِرِينَ","aya_text_emlaey":"ويقولون لولا أنـزل عليه آية من ربه فقل إنما الغيب لله فانتظروا إني معكم من المنتظرين","aya_tafseer":"[20] ويقول هؤلاء الكفرة المعاندون: هلَّا أُنزل على محمد علم ودليل، وآية حسية من ربه نعلم بها أنه على حق فيما يقول، فقل لهم -أيها الرسول-: لا يعلم الغيب أحد إلا الله، فإن شاء فعل وإن شاء لم يفعل، فانتظروا -أيها القوم- قضاء الله بيننا وبينكم بتعجيل عقوبته للمبطل منا، ونصرة صاحب الحق، إني منتظر ذلك."},{"id":"1385","jozz":"11","page":"211","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"1","line_end":"2","aya_no":"21","aya_text":"وَإِذَآ أَذَقۡنَا ٱلنَّاسَ رَحۡمَةٗ مِّنۢ بَعۡدِ ضَرَّآءَ مَسَّتۡهُمۡ إِذَا لَهُم مَّكۡرٞ فِيٓ ءَايَاتِنَاۚ قُلِ ٱللَّهُ أَسۡرَعُ مَكۡرًاۚ إِنَّ رُسُلَنَا يَكۡتُبُونَ مَا تَمۡكُرُونَ","aya_text_emlaey":"وإذا أذقنا الناس رحمة من بعد ضراء مستهم إذا لهم مكر في آياتنا قل الله أسرع مكرا إن رسلنا يكتبون ما تمكرون","aya_tafseer":"[21] وإذا أذقنا المشركين يسراً وفرجاً ورخاءً بعد عُسْرٍ وشدة وكرب أصابهم، إذا هم يكذِّبون، ويستهزئون بآيات الله، قل -أيها الرسول- لهؤلاء المشركين المستهزئين: الله أسرع مكراً واستدراجاً وعقوبة لكم. إن حَفَظَتَنا الذين نرسلهم إليكم يكتبون عليكم ما تمكرون في آياتنا، ثم نحاسبكم على ذلك."},{"id":"1386","jozz":"11","page":"211","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"3","line_end":"7","aya_no":"22","aya_text":"هُوَ ٱلَّذِي يُسَيِّرُكُمۡ فِي ٱلۡبَرِّ وَٱلۡبَحۡرِۖ حَتَّىٰٓ إِذَا كُنتُمۡ فِي ٱلۡفُلۡكِ وَجَرَيۡنَ بِهِم بِرِيحٖ طَيِّبَةٖ وَفَرِحُواْ بِهَا جَآءَتۡهَا رِيحٌ عَاصِفٞ وَجَآءَهُمُ ٱلۡمَوۡجُ مِن كُلِّ مَكَانٖ وَظَنُّوٓاْ أَنَّهُمۡ أُحِيطَ بِهِمۡ دَعَوُاْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ لَئِنۡ أَنجَيۡتَنَا مِنۡ هَٰذِهِۦ لَنَكُونَنَّ مِنَ ٱلشَّٰكِرِينَ","aya_text_emlaey":"هو الذي يسيركم في البر والبحر حتى إذا كنتم في الفلك وجرين بهم بريح طيبة وفرحوا بها جاءتها ريح عاصف وجاءهم الموج من كل مكان وظنوا أنهم أحيط بهم دعوا الله مخلصين له الدين لئن أنجيتنا من هذه لنكونن من الشاكرين","aya_tafseer":"[22] هو الذي يسيِّركم -أيها الناس- في البر على الدواب وغيرها، وفي البحر في السُّفُن، حتى إذا كنتم فيها وجرت بريح طيبة، وفرح ركاب السفن بالريح الطيبة، جاءت هذه السفنَ ريحٌ شديدة، وجاء الركابَ الموجُ (وهو ما ارتفع من الماء) من كل مكان، وأيقنوا أن الهلاك قد أحاط بهم، أخلصوا الدعاء لله وحده، وتركوا ما كانوا يعبدون، وقالوا: لئن أنجيتنا من هذه الشدة التي نحن فيها لنكونن من الشاكرين لك على نِعَمك."},{"id":"1387","jozz":"11","page":"211","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"7","line_end":"9","aya_no":"23","aya_text":"فَلَمَّآ أَنجَىٰهُمۡ إِذَا هُمۡ يَبۡغُونَ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّۗ يَٰٓأَيُّهَا ٱلنَّاسُ إِنَّمَا بَغۡيُكُمۡ عَلَىٰٓ أَنفُسِكُمۖ مَّتَٰعَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ ثُمَّ إِلَيۡنَا مَرۡجِعُكُمۡ فَنُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ","aya_text_emlaey":"فلما أنجاهم إذا هم يبغون في الأرض بغير الحق ياأيها الناس إنما بغيكم على أنفسكم متاع الحياة الدنيا ثم إلينا مرجعكم فننبئكم بما كنتم تعملون","aya_tafseer":"[23] فلما أنجاهم الله من الشدائد والأهوال إذا هم يعملون في الأرض بالفساد وبالمعاصي. يا أيها الناس إنما وَبالُ بغيكم راجع على أنفسكم، تمتعون به متاعاً غير دائم في الحياة الدنيا الزائلة، ثم إلينا مصيركم ومرجعكم، فنخبركم بجميع أعمالكم، ونحاسبكم عليها."},{"id":"1388","jozz":"11","page":"211","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"10","line_end":"14","aya_no":"24","aya_text":"إِنَّمَا مَثَلُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا كَمَآءٍ أَنزَلۡنَٰهُ مِنَ ٱلسَّمَآءِ فَٱخۡتَلَطَ بِهِۦ نَبَاتُ ٱلۡأَرۡضِ مِمَّا يَأۡكُلُ ٱلنَّاسُ وَٱلۡأَنۡعَٰمُ حَتَّىٰٓ إِذَآ أَخَذَتِ ٱلۡأَرۡضُ زُخۡرُفَهَا وَٱزَّيَّنَتۡ وَظَنَّ أَهۡلُهَآ أَنَّهُمۡ قَٰدِرُونَ عَلَيۡهَآ أَتَىٰهَآ أَمۡرُنَا لَيۡلًا أَوۡ نَهَارٗا فَجَعَلۡنَٰهَا حَصِيدٗا كَأَن لَّمۡ تَغۡنَ بِٱلۡأَمۡسِۚ كَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَتَفَكَّرُونَ","aya_text_emlaey":"إنما مثل الحياة الدنيا كماء أنـزلناه من السماء فاختلط به نبات الأرض مما يأكل الناس والأنعام حتى إذا أخذت الأرض زخرفها وازينت وظن أهلها أنهم قادرون عليها أتاها أمرنا ليلا أو نهارا فجعلناها حصيدا كأن لم تغن بالأمس كذلك نفصل الآيات لقوم يتفكرون","aya_tafseer":"[24] إنما مثل الحياة الدنيا، وما تتفاخرون به فيها من زينة وأموال، كمثل مطر أنزلناه من السماء إلى الأرض، فنبتت به أنواع من النبات، مختلط بعضها ببعض مما يقتات به الناس من الثمار، وما تأكله الحيوانات من النبات، حتى إذا ظهر حُسْنُ هذه الأرض وبهاؤها، وظن أهل هذه الأرض أنهم قادرون على حصادها والانتفاع بها، جاءها أمرنا وقضاؤنا بهلاك ما عليها من النبات والزينة، إما ليلاً وإما نهاراً، فجعلنا هذه النباتاتِ والأشجارَ محصودة مقطوعة لا شيء فيها، كأن لم تكن تلك الزروع والنباتات قائمة قبل ذلك على وجه الأرض، فكذلك يأتي الفناء على ما تتباهَون به من دنياكم وزخارفها فيفنيها الله ويهلكها. وكما بيَّنا لكم -أيها الناس- مَثَلَ هذه الدنيا وعرَّفناكم بحقيقتها، نبيِّن حججنا وأدلتنا لقوم يتفكرون في آيات الله، ويتدبرون ما ينفعهم في الدنيا والآخرة."},{"id":"1389","jozz":"11","page":"211","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"14","line_end":"15","aya_no":"25","aya_text":"وَٱللَّهُ يَدۡعُوٓاْ إِلَىٰ دَارِ ٱلسَّلَٰمِ وَيَهۡدِي مَن يَشَآءُ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ","aya_text_emlaey":"والله يدعو إلى دار السلام ويهدي من يشاء إلى صراط مستقيم","aya_tafseer":"[25] والله يدعوكم إلى جناته التي أعدَّها لأوليائه، ويهدي مَن يشاء مِن خَلْقه، فيوفقه لإصابة الطريق المستقيم، وهو الإسلام."},{"id":"1390","jozz":"11","page":"212","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"1","line_end":"2","aya_no":"26","aya_text":"۞ لِّلَّذِينَ أَحۡسَنُواْ ٱلۡحُسۡنَىٰ وَزِيَادَةٞۖ وَلَا يَرۡهَقُ وُجُوهَهُمۡ قَتَرٞ وَلَا ذِلَّةٌۚ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلۡجَنَّةِۖ هُمۡ فِيهَا خَٰلِدُونَ","aya_text_emlaey":"للذين أحسنوا الحسنى وزيادة ولا يرهق وجوههم قتر ولا ذلة أولئك أصحاب الجنة هم فيها خالدون","aya_tafseer":"[26] للمؤمنين الذين أحسنوا عبادة الله فأطاعوه فيما أمر ونهى، الجنةُ، وزيادة عليها، وهي النظر إلى وجه الله تعالى في الجنة، والمغفرةُ والرضوان، ولا يغشى وجوههم غبار ولا ذلة، كما يلحق أهل النار. هؤلاء المتصفون بهذه الصفات هم أصحاب الجنة ماكثون فيها أبداً."},{"id":"1391","jozz":"11","page":"212","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"2","line_end":"5","aya_no":"27","aya_text":"وَٱلَّذِينَ كَسَبُواْ ٱلسَّيِّـَٔاتِ جَزَآءُ سَيِّئَةِۭ بِمِثۡلِهَا وَتَرۡهَقُهُمۡ ذِلَّةٞۖ مَّا لَهُم مِّنَ ٱللَّهِ مِنۡ عَاصِمٖۖ كَأَنَّمَآ أُغۡشِيَتۡ وُجُوهُهُمۡ قِطَعٗا مِّنَ ٱلَّيۡلِ مُظۡلِمًاۚ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ","aya_text_emlaey":"والذين كسبوا السيئات جزاء سيئة بمثلها وترهقهم ذلة ما لهم من الله من عاصم كأنما أغشيت وجوههم قطعا من الليل مظلما أولئك أصحاب النار هم فيها خالدون","aya_tafseer":"[27] والذين عملوا السيئات في الدنيا فكفروا وعصَوا الله لهم جزاء أعمالهم السيئة التي عملوها بمثلها من عقاب الله في الآخرة، وتغشاهم ذلَّة وهوان، وليس لهم مِن عذاب الله مِن مانع يمنعهم إذا عاقبهم، كأنما أُلبست وجوههم أجزاءً من سواد الليل المظلم. هؤلاء هم أهل النار ماكثون فيها أبداً."},{"id":"1392","jozz":"11","page":"212","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"5","line_end":"7","aya_no":"28","aya_text":"وَيَوۡمَ نَحۡشُرُهُمۡ جَمِيعٗا ثُمَّ نَقُولُ لِلَّذِينَ أَشۡرَكُواْ مَكَانَكُمۡ أَنتُمۡ وَشُرَكَآؤُكُمۡۚ فَزَيَّلۡنَا بَيۡنَهُمۡۖ وَقَالَ شُرَكَآؤُهُم مَّا كُنتُمۡ إِيَّانَا تَعۡبُدُونَ","aya_text_emlaey":"ويوم نحشرهم جميعا ثم نقول للذين أشركوا مكانكم أنتم وشركاؤكم فزيلنا بينهم وقال شركاؤهم ما كنتم إيانا تعبدون","aya_tafseer":"[28] واذكر -أيها الرسول- يوم نحشر الخلق جميعاً للحساب والجزاء، ثم نقول للذين أشركوا بالله: الزموا مكانكم أنتم وشركاؤكم الذين كنتم تعبدونهم مِن دون الله حتى تنظروا ما يُفْعل بكم، فَفَرَّقْنا بين المشركين ومعبوديهم، وتبرَّأ مَن عُبِدُوا مِن دون الله ممن كانوا يعبدونهم، وقالوا للمشركين: ما كنتم إيانا تعبدون في الدنيا."},{"id":"1393","jozz":"11","page":"212","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"7","line_end":"8","aya_no":"29","aya_text":"فَكَفَىٰ بِٱللَّهِ شَهِيدَۢا بَيۡنَنَا وَبَيۡنَكُمۡ إِن كُنَّا عَنۡ عِبَادَتِكُمۡ لَغَٰفِلِينَ","aya_text_emlaey":"فكفى بالله شهيدا بيننا وبينكم إن كنا عن عبادتكم لغافلين","aya_tafseer":"[29] فكفى بالله شهيداً بيننا وبينكم، إننا لم نكن نعلم ما كنتم تقولون وتفعلون، ولقد كنَّا عن عبادتكم إيانا غافلين، لا نشعر بها."},{"id":"1394","jozz":"11","page":"212","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"9","line_end":"10","aya_no":"30","aya_text":"هُنَالِكَ تَبۡلُواْ كُلُّ نَفۡسٖ مَّآ أَسۡلَفَتۡۚ وَرُدُّوٓاْ إِلَى ٱللَّهِ مَوۡلَىٰهُمُ ٱلۡحَقِّۖ وَضَلَّ عَنۡهُم مَّا كَانُواْ يَفۡتَرُونَ","aya_text_emlaey":"هنالك تبلو كل نفس ما أسلفت وردوا إلى الله مولاهم الحق وضل عنهم ما كانوا يفترون","aya_tafseer":"[30] في ذلك الموقف للحساب تتفقد كل نفس أحوالها وأعمالها التي سلفت وتعاينها، وتجازى بحسبها: إن خيراً فخير، وإن شرّاً فشر، ورُدَّ الجميع إلى الله الحكم العدل، فأُدخِلَ أهلُ الجنةِ الجنةَ وأهل النار النار، وذهب عن المشركين ما كانوا يعبدون من دون الله افتراء عليه."},{"id":"1395","jozz":"11","page":"212","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"10","line_end":"13","aya_no":"31","aya_text":"قُلۡ مَن يَرۡزُقُكُم مِّنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِ أَمَّن يَمۡلِكُ ٱلسَّمۡعَ وَٱلۡأَبۡصَٰرَ وَمَن يُخۡرِجُ ٱلۡحَيَّ مِنَ ٱلۡمَيِّتِ وَيُخۡرِجُ ٱلۡمَيِّتَ مِنَ ٱلۡحَيِّ وَمَن يُدَبِّرُ ٱلۡأَمۡرَۚ فَسَيَقُولُونَ ٱللَّهُۚ فَقُلۡ أَفَلَا تَتَّقُونَ","aya_text_emlaey":"قل من يرزقكم من السماء والأرض أمن يملك السمع والأبصار ومن يخرج الحي من الميت ويخرج الميت من الحي ومن يدبر الأمر فسيقولون الله فقل أفلا تتقون","aya_tafseer":"[31] قل -أيها الرسول- لهؤلاء المشركين: مَن يرزقكم من السماء، بما يُنزله من المطر، ومن الأرض بما ينبته فيها من أنواع النبات والشجر تأكلون منه أنتم وأنعامكم؟ ومَن يملك ما تتمتعون به أنتم وغيركم مِن حواسِّ السمع والأبصار؟ ومن ذا الذي يملك الحياة والموت في الكون كلِّه، فيخرج الأحياء والأموات بعضها من بعض فيما تعرفون من المخلوقات، وفيما لا تعرفون؟ ومَن يدبِّر أمر السماء والأرض وما فيهن، وأمركم وأمر الخليقة جميعاً؟ فسوف يجيبونك بأن الذي يفعل ذلك كله هو الله، فقل لهم: أفلا تخافون عقاب الله إن عبدتم معه غيره؟"},{"id":"1396","jozz":"11","page":"212","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"13","line_end":"14","aya_no":"32","aya_text":"فَذَٰلِكُمُ ٱللَّهُ رَبُّكُمُ ٱلۡحَقُّۖ فَمَاذَا بَعۡدَ ٱلۡحَقِّ إِلَّا ٱلضَّلَٰلُۖ فَأَنَّىٰ تُصۡرَفُونَ","aya_text_emlaey":"فذلكم الله ربكم الحق فماذا بعد الحق إلا الضلال فأنى تصرفون","aya_tafseer":"[32] فذلكم الله ربكم هو الحق الذي لا ريب فيه، المستَحِق للعبادة وحده لا شريك له، فأي شيء سوى الحق إلا الضلال؟ فكيف تُصْرَفون عن عبادته إلى عبادة ما سواه؟"},{"id":"1397","jozz":"11","page":"212","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"14","line_end":"15","aya_no":"33","aya_text":"كَذَٰلِكَ حَقَّتۡ كَلِمَتُ رَبِّكَ عَلَى ٱلَّذِينَ فَسَقُوٓاْ أَنَّهُمۡ لَا يُؤۡمِنُونَ","aya_text_emlaey":"كذلك حقت كلمت ربك على الذين فسقوا أنهم لا يؤمنون","aya_tafseer":"[33] كما كفر هؤلاء المشركون واستمرُّوا على شركهم، حقت كلمة ربك وحكمه وقضاؤه على الذين خرجوا عن طاعة ربهم إلى معصيته وكفروا به أنَّهم لا يصدقون بوحدانية الله، ولا بنبوة نبيِّه محمد -صلى الله عليه وسلم-، ولا يعملون بهديه."},{"id":"1398","jozz":"11","page":"213","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"1","line_end":"2","aya_no":"34","aya_text":"قُلۡ هَلۡ مِن شُرَكَآئِكُم مَّن يَبۡدَؤُاْ ٱلۡخَلۡقَ ثُمَّ يُعِيدُهُۥۚ قُلِ ٱللَّهُ يَبۡدَؤُاْ ٱلۡخَلۡقَ ثُمَّ يُعِيدُهُۥۖ فَأَنَّىٰ تُؤۡفَكُونَ","aya_text_emlaey":"قل هل من شركائكم من يبدأ الخلق ثم يعيده قل الله يبدأ الخلق ثم يعيده فأنى تؤفكون","aya_tafseer":"[34] قل لهم -أيها الرسول-: هل من آلهتكم ومعبوداتكم مَن يبدأ خَلْق أي شيء من غير أصل، ثم يفنيه بعد إنشائه، ثم يعيده كهيئته قبل أن يفنيه؟ فإنهم لا يقدرون على دعوى ذلك، قل -أيها الرسول-: الله تعالى وحده هو الذي ينشئ الخلق ثم يفنيه ثم يعيده، فكيف تنصرفون عن طريق الحق إلى الباطل، وهو عبادة غير الله؟"},{"id":"1399","jozz":"11","page":"213","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"2","line_end":"4","aya_no":"35","aya_text":"قُلۡ هَلۡ مِن شُرَكَآئِكُم مَّن يَهۡدِيٓ إِلَى ٱلۡحَقِّۚ قُلِ ٱللَّهُ يَهۡدِي لِلۡحَقِّۗ أَفَمَن يَهۡدِيٓ إِلَى ٱلۡحَقِّ أَحَقُّ أَن يُتَّبَعَ أَمَّن لَّا يَهِدِّيٓ إِلَّآ أَن يُهۡدَىٰۖ فَمَا لَكُمۡ كَيۡفَ تَحۡكُمُونَ","aya_text_emlaey":"قل هل من شركائكم من يهدي إلى الحق قل الله يهدي للحق أفمن يهدي إلى الحق أحق أن يتبع أمن لا يهدي إلا أن يهدى فما لكم كيف تحكمون","aya_tafseer":"[35] قل -أيها الرسول- لهؤلاء المشركين: هل مِن شركائكم مَن يرشد إلى الطريق المستقيم؟ فإنهم لا يقدرون على ذلك، قل لهم: الله وحده يهدي الضال عن الهدى إلى الحق. أيهما أحق بالاتباع: مَن يهدي وحده للحق أم من لا يهتدي لعدم علمه ولضلاله، وهم شركاؤكم الذين لا يَهْدون ولا يَهْتَدُون إلَّا أن يُهْدَوا؟ فما بالكم كيف سوَّيتم بين الله وخلقه؟ وهذا حكم باطل."},{"id":"1400","jozz":"11","page":"213","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"5","line_end":"6","aya_no":"36","aya_text":"وَمَا يَتَّبِعُ أَكۡثَرُهُمۡ إِلَّا ظَنًّاۚ إِنَّ ٱلظَّنَّ لَا يُغۡنِي مِنَ ٱلۡحَقِّ شَيۡـًٔاۚ إِنَّ ٱللَّهَ عَلِيمُۢ بِمَا يَفۡعَلُونَ","aya_text_emlaey":"وما يتبع أكثرهم إلا ظنا إن الظن لا يغني من الحق شيئا إن الله عليم بما يفعلون","aya_tafseer":"[36] وما يتبع أكثر هؤلاء المشركين في جعلهم الأصنام آلهة واعتقادهم بأنها تقرِّب إلى الله إلا تخرصاً وظنّاً، وهو لا يغني من اليقين شيئاً. إن الله عليم بما يفعل هؤلاء المشركون من الكفر والتكذيب."},{"id":"1401","jozz":"11","page":"213","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"6","line_end":"8","aya_no":"37","aya_text":"وَمَا كَانَ هَٰذَا ٱلۡقُرۡءَانُ أَن يُفۡتَرَىٰ مِن دُونِ ٱللَّهِ وَلَٰكِن تَصۡدِيقَ ٱلَّذِي بَيۡنَ يَدَيۡهِ وَتَفۡصِيلَ ٱلۡكِتَٰبِ لَا رَيۡبَ فِيهِ مِن رَّبِّ ٱلۡعَٰلَمِينَ","aya_text_emlaey":"وما كان هذا القرآن أن يفترى من دون الله ولكن تصديق الذي بين يديه وتفصيل الكتاب لا ريب فيه من رب العالمين","aya_tafseer":"[37] وما كان يتهيَّأ لأحد أن يأتي بهذا القرآن مِن عند غير الله؛ لأنه لا يقدر على ذلك أحد من الخلق، ولكن الله أنزله مصدِّقاً للكتب التي أنزلها على أنبيائه؛ لأن دين الله واحد، وفي هذا القرآن بيان وتفصيل لما شرعه الله لأمة محمد -صلى الله عليه وسلم-، لا شك في أن هذا القرآن موحىً من رب العالمين."},{"id":"1402","jozz":"11","page":"213","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"8","line_end":"9","aya_no":"38","aya_text":"أَمۡ يَقُولُونَ ٱفۡتَرَىٰهُۖ قُلۡ فَأۡتُواْ بِسُورَةٖ مِّثۡلِهِۦ وَٱدۡعُواْ مَنِ ٱسۡتَطَعۡتُم مِّن دُونِ ٱللَّهِ إِن كُنتُمۡ صَٰدِقِينَ","aya_text_emlaey":"أم يقولون افتراه قل فأتوا بسورة مثله وادعوا من استطعتم من دون الله إن كنتم صادقين","aya_tafseer":"[38] بل أيقولون: إن هذا القرآن افتراه محمد من عند نفسه؟ فإنهم يعلمون أنه بشر مثلهم! قل لهم -أيها الرسول-: فأتوا أنتم بسورة واحدة من جنس هذا القرآن في نظمه وهدايته، واستعينوا على ذلك بكل مَن قَدَرْتم عليه من دون الله من إنس وجن، إن كنتم صادقين في دعواكم."},{"id":"1403","jozz":"11","page":"213","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"10","line_end":"11","aya_no":"39","aya_text":"بَلۡ كَذَّبُواْ بِمَا لَمۡ يُحِيطُواْ بِعِلۡمِهِۦ وَلَمَّا يَأۡتِهِمۡ تَأۡوِيلُهُۥۚ كَذَٰلِكَ كَذَّبَ ٱلَّذِينَ مِن قَبۡلِهِمۡۖ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلظَّٰلِمِينَ","aya_text_emlaey":"بل كذبوا بما لم يحيطوا بعلمه ولما يأتهم تأويله كذلك كذب الذين من قبلهم فانظر كيف كان عاقبة الظالمين","aya_tafseer":"[39] بل سارَعوا إلى التكذيب بالقرآن أول ما سمعوه، قبل أن يتدبروا آياته، وكفروا بما لم يحيطوا بعلمه من ذكر البعث والجزاء والجنة والنار وغير ذلك، ولم يأتهم بعدُ حقيقة ما وُعِدوا به في الكتاب. وكما كذَّب المشركون بوعيد الله كذَّبت الأمم التي خلت قبلهم، فانظر -أيها الرسول- كيف كانت عاقبة الظالمين؟ فقد أهلك الله بعضهم بالخسف، وبعضهم بالغرق، وبعضهم بغير ذلك."},{"id":"1404","jozz":"11","page":"213","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"12","line_end":"13","aya_no":"40","aya_text":"وَمِنۡهُم مَّن يُؤۡمِنُ بِهِۦ وَمِنۡهُم مَّن لَّا يُؤۡمِنُ بِهِۦۚ وَرَبُّكَ أَعۡلَمُ بِٱلۡمُفۡسِدِينَ","aya_text_emlaey":"ومنهم من يؤمن به ومنهم من لا يؤمن به وربك أعلم بالمفسدين","aya_tafseer":"[40] ومِن قومك -أيها الرسول- مَن يصدِّق بالقرآن، ومنهم مَن لا يصدِّق به حتى يموت على ذلك ويبعث عليه، وربك أعلم بالمفسدين الذين لا يؤمنون به، على وجه الظلم والعناد والفساد، فيجازيهم على فسادهم بأشد العذاب."},{"id":"1405","jozz":"11","page":"213","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"13","line_end":"14","aya_no":"41","aya_text":"وَإِن كَذَّبُوكَ فَقُل لِّي عَمَلِي وَلَكُمۡ عَمَلُكُمۡۖ أَنتُم بَرِيٓـُٔونَ مِمَّآ أَعۡمَلُ وَأَنَا۠ بَرِيٓءٞ مِّمَّا تَعۡمَلُونَ","aya_text_emlaey":"وإن كذبوك فقل لي عملي ولكم عملكم أنتم بريئون مما أعمل وأنا بريء مما تعملون","aya_tafseer":"[41] وإن كذَّبك -أيها الرسول- هؤلاء المشركون فقل لهم: لي ديني وعملي، ولكم دينكم وعملكم، فأنتم لا تؤاخَذُون بعملي، وأنا لا أؤاخَذ بعملكم."},{"id":"1406","jozz":"11","page":"213","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"14","line_end":"15","aya_no":"42","aya_text":"وَمِنۡهُم مَّن يَسۡتَمِعُونَ إِلَيۡكَۚ أَفَأَنتَ تُسۡمِعُ ٱلصُّمَّ وَلَوۡ كَانُواْ لَا يَعۡقِلُونَ","aya_text_emlaey":"ومنهم من يستمعون إليك أفأنت تسمع الصم ولو كانوا لا يعقلون","aya_tafseer":"[42] و مِنَ الكفار مَن يسمعون كلامك الحق، وتلاوتك القرآن، ولكنهم لا يهتدون. أفأنت تقدر على إسماع الصم؟ فكذلك لا تقدر على هداية هؤلاء إلا أن يشاء الله هدايتهم؛ لأنهم صُمٌّ عن سماع الحق، لا يعقلونه."},{"id":"1407","jozz":"11","page":"214","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"1","line_end":"1","aya_no":"43","aya_text":"وَمِنۡهُم مَّن يَنظُرُ إِلَيۡكَۚ أَفَأَنتَ تَهۡدِي ٱلۡعُمۡيَ وَلَوۡ كَانُواْ لَا يُبۡصِرُونَ","aya_text_emlaey":"ومنهم من ينظر إليك أفأنت تهدي العمي ولو كانوا لا يبصرون","aya_tafseer":"[43] ومِنَ الكفار مَن ينظر إليك وإلى أدلة نبوتك الصادقة، ولكنه لا يبصر ما آتاك الله من نور الإيمان، أفأنت -أيها الرسول- تقدر على أن تخلق للعمي أبصاراً يهتدون بها؟ فكذلك لا تقدر على هدايتهم إذا كانوا فاقدي البصيرة، و إنما ذلك كلُّه لله وحده."},{"id":"1408","jozz":"11","page":"214","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"2","line_end":"3","aya_no":"44","aya_text":"إِنَّ ٱللَّهَ لَا يَظۡلِمُ ٱلنَّاسَ شَيۡـٔٗا وَلَٰكِنَّ ٱلنَّاسَ أَنفُسَهُمۡ يَظۡلِمُونَ","aya_text_emlaey":"إن الله لا يظلم الناس شيئا ولكن الناس أنفسهم يظلمون","aya_tafseer":"[44] إن الله لا يظلم الناس شيئاً بزيادة في سيئاتهم أو نقص من حسناتهم، ولكن الناس هم الذين يظلمون أنفسهم بالكفر والمعصية ومخالفة أمر الله ونهيه."},{"id":"1409","jozz":"11","page":"214","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"3","line_end":"5","aya_no":"45","aya_text":"وَيَوۡمَ يَحۡشُرُهُمۡ كَأَن لَّمۡ يَلۡبَثُوٓاْ إِلَّا سَاعَةٗ مِّنَ ٱلنَّهَارِ يَتَعَارَفُونَ بَيۡنَهُمۡۚ قَدۡ خَسِرَ ٱلَّذِينَ كَذَّبُواْ بِلِقَآءِ ٱللَّهِ وَمَا كَانُواْ مُهۡتَدِينَ","aya_text_emlaey":"ويوم يحشرهم كأن لم يلبثوا إلا ساعة من النهار يتعارفون بينهم قد خسر الذين كذبوا بلقاء الله وما كانوا مهتدين","aya_tafseer":"[45] ويوم يَحشر الله هؤلاء المشركين يوم البعث والحساب، كأنهم قبل ذلك لم يمكثوا في الحياة الدنيا إلا قدر ساعة من النهار، يعرف بعضهم بعضاً كحالهم في الدنيا، ثم انقطعت تلك المعرفة وانقضت تلك الساعة. قد خسر الذين كفروا وكذَّبوا بلقاء الله وثوابه وعقابه، وما كانوا موفَّقين لإصابة الرشد فيما فعلوا."},{"id":"1410","jozz":"11","page":"214","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"5","line_end":"6","aya_no":"46","aya_text":"وَإِمَّا نُرِيَنَّكَ بَعۡضَ ٱلَّذِي نَعِدُهُمۡ أَوۡ نَتَوَفَّيَنَّكَ فَإِلَيۡنَا مَرۡجِعُهُمۡ ثُمَّ ٱللَّهُ شَهِيدٌ عَلَىٰ مَا يَفۡعَلُونَ","aya_text_emlaey":"وإما نرينك بعض الذي نعدهم أو نتوفينك فإلينا مرجعهم ثم الله شهيد على ما يفعلون","aya_tafseer":"[46] وإمَّا نرينَّك -أيها الرسول- في حياتك بعض الذي نَعِدُهم من العقاب في الدنيا، أو نتوفينك قبل أن نريك ذلك فيهم، فإلينا وحدنا يرجع أمرهم في الحالتين، ثم الله شهيد على أفعالهم التي كانوا يفعلونها في الدنيا، لا يخفى عليه شيء منها، فيجازيهم بها جزاءهم الذي يستحقونه."},{"id":"1411","jozz":"11","page":"214","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"6","line_end":"8","aya_no":"47","aya_text":"وَلِكُلِّ أُمَّةٖ رَّسُولٞۖ فَإِذَا جَآءَ رَسُولُهُمۡ قُضِيَ بَيۡنَهُم بِٱلۡقِسۡطِ وَهُمۡ لَا يُظۡلَمُونَ","aya_text_emlaey":"ولكل أمة رسول فإذا جاء رسولهم قضي بينهم بالقسط وهم لا يظلمون","aya_tafseer":"[47] ولكل أمة خَلَتْ قبلكم -أيها الناس- رسول أرسلتُه إليهم، كما أرسلت محمداً إليكم يدعو إلى دين الله وطاعته، فإذا جاء رسولهم في الآخرة قُضِيَ حينئذ بينهم بالعدل، وهم لا يُظلمون مِن جزاء أعمالهم شيئاً."},{"id":"1412","jozz":"11","page":"214","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"8","line_end":"8","aya_no":"48","aya_text":"وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَٰدِقِينَ","aya_text_emlaey":"ويقولون متى هذا الوعد إن كنتم صادقين","aya_tafseer":"[48] ويقول المشركون من قومك -أيها الرسول-: متى قيام الساعة إن كنت أنت ومَن تبعك من الصادقين فيما تَعِدوننا به؟"},{"id":"1413","jozz":"11","page":"214","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"9","line_end":"10","aya_no":"49","aya_text":"قُل لَّآ أَمۡلِكُ لِنَفۡسِي ضَرّٗا وَلَا نَفۡعًا إِلَّا مَا شَآءَ ٱللَّهُۗ لِكُلِّ أُمَّةٍ أَجَلٌۚ إِذَا جَآءَ أَجَلُهُمۡ فَلَا يَسۡتَـٔۡخِرُونَ سَاعَةٗ وَلَا يَسۡتَقۡدِمُونَ","aya_text_emlaey":"قل لا أملك لنفسي ضرا ولا نفعا إلا ما شاء الله لكل أمة أجل إذا جاء أجلهم فلا يستأخرون ساعة ولا يستقدمون","aya_tafseer":"[49] قل لهم -أيها الرسول-: لا أستطيع أن أدفع عن نفسي ضرّاً، ولا أجلب لها نفعاً، إلا ما شاء الله أن يدفع عني مِن ضرٍّ أو يجلب لي من نفع. لكل قوم وقت لانقضاء مدتهم وأجلهم، إذا جاء وقت انقضاء أجلهم وفناء أعمارهم، فلا يستأخرون عنه ساعة فيُمْهلون، ولا يتقدم أجلهم عن الوقت المعلوم."},{"id":"1414","jozz":"11","page":"214","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"11","line_end":"12","aya_no":"50","aya_text":"قُلۡ أَرَءَيۡتُمۡ إِنۡ أَتَىٰكُمۡ عَذَابُهُۥ بَيَٰتًا أَوۡ نَهَارٗا مَّاذَا يَسۡتَعۡجِلُ مِنۡهُ ٱلۡمُجۡرِمُونَ","aya_text_emlaey":"قل أرأيتم إن أتاكم عذابه بياتا أو نهارا ماذا يستعجل منه المجرمون","aya_tafseer":"[50] قل -أيها الرسول- لهؤلاء المشركين: أخبروني إن أتاكم عذاب الله ليلاً أو نهاراً، فأي شيء تستعجلون أيها المجرمون بنزول العذاب؟"},{"id":"1415","jozz":"11","page":"214","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"12","line_end":"13","aya_no":"51","aya_text":"أَثُمَّ إِذَا مَا وَقَعَ ءَامَنتُم بِهِۦٓۚ ءَآلۡـَٰٔنَ وَقَدۡ كُنتُم بِهِۦ تَسۡتَعۡجِلُونَ","aya_text_emlaey":"أثم إذا ما وقع آمنتم به آلآن وقد كنتم به تستعجلون","aya_tafseer":"[51] أبعدما وقع عذاب الله بكم -أيها المشركون- آمنتم في وقت لا ينفعكم فيه الإيمان؟ وقيل لكم حينئذ: آلآن تؤمنون به، وقد كنتم من قبل تستعجلون به؟"},{"id":"1416","jozz":"11","page":"214","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"13","line_end":"14","aya_no":"52","aya_text":"ثُمَّ قِيلَ لِلَّذِينَ ظَلَمُواْ ذُوقُواْ عَذَابَ ٱلۡخُلۡدِ هَلۡ تُجۡزَوۡنَ إِلَّا بِمَا كُنتُمۡ تَكۡسِبُونَ","aya_text_emlaey":"ثم قيل للذين ظلموا ذوقوا عذاب الخلد هل تجزون إلا بما كنتم تكسبون","aya_tafseer":"[52] ثم قيل للذين ظلموا أنفسهم بكفرهم بالله: تجرَّعوا عذاب الله الدائم لكم أبداً، فهل تُعاقَبون إلا بما كنتم تعملون في حياتكم من معاصي الله؟"},{"id":"1417","jozz":"11","page":"214","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"14","line_end":"15","aya_no":"53","aya_text":"۞ وَيَسۡتَنۢبِـُٔونَكَ أَحَقٌّ هُوَۖ قُلۡ إِي وَرَبِّيٓ إِنَّهُۥ لَحَقّٞۖ وَمَآ أَنتُم بِمُعۡجِزِينَ","aya_text_emlaey":"ويستنبئونك أحق هو قل إي وربي إنه لحق وما أنتم بمعجزين","aya_tafseer":"[53] ويستخبرك هؤلاء المشركون من قومك -أيها الرسول- عن العذاب يوم القيامة، أحقٌّ هو؟ قل لهم -أيها الرسول-: نعم وربي إنه لحق لا شك فيه، وما أنتم بمعجزين الله أن يبعثكم ويجازيكم، فأنتم في قبضته وسلطانه."},{"id":"1418","jozz":"11","page":"215","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"1","line_end":"3","aya_no":"54","aya_text":"وَلَوۡ أَنَّ لِكُلِّ نَفۡسٖ ظَلَمَتۡ مَا فِي ٱلۡأَرۡضِ لَٱفۡتَدَتۡ بِهِۦۗ وَأَسَرُّواْ ٱلنَّدَامَةَ لَمَّا رَأَوُاْ ٱلۡعَذَابَۖ وَقُضِيَ بَيۡنَهُم بِٱلۡقِسۡطِ وَهُمۡ لَا يُظۡلَمُونَ","aya_text_emlaey":"ولو أن لكل نفس ظلمت ما في الأرض لافتدت به وأسروا الندامة لما رأوا العذاب وقضي بينهم بالقسط وهم لا يظلمون","aya_tafseer":"[54] ولو أن لكل نفس أشركت وكفرت بالله جميع ما في الأرض، وأمكنها أن تجعله فداءً لها من ذلك العذاب لافتدت به، وأخفى الذين ظلموا حسرتهم حين أبصروا عذاب الله واقعاً بهم جميعاً، وقضى الله عز وجل بينهم بالعدل، وهم لا يُظلَمون؛ لأن الله تعالى لا يعاقب أحداً إلا بذنبه."},{"id":"1419","jozz":"11","page":"215","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"3","line_end":"4","aya_no":"55","aya_text":"أَلَآ إِنَّ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ أَلَآ إِنَّ وَعۡدَ ٱللَّهِ حَقّٞ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ","aya_text_emlaey":"ألا إن لله ما في السموات والأرض ألا إن وعد الله حق ولكن أكثرهم لا يعلمون","aya_tafseer":"[55] ألا إن كل ما في السموات وما في الأرض ملك لله تعالى، لا شيء من ذلك لأحد سواه. ألا إن لقاء الله تعالى وعذابه للمشركين كائن، ولكن أكثرهم لا يعلمون حقيقة ذلك."},{"id":"1420","jozz":"11","page":"215","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"4","line_end":"5","aya_no":"56","aya_text":"هُوَ يُحۡيِۦ وَيُمِيتُ وَإِلَيۡهِ تُرۡجَعُونَ","aya_text_emlaey":"هو يحيي ويميت وإليه ترجعون","aya_tafseer":"[56] إن الله هو المحيي والمميت لا يتعذَّر عليه إحياء الناس بعد موتهم، كما لا تعجزه إماتتهم إذا أراد ذلك، وهم إليه راجعون بعد موتهم."},{"id":"1421","jozz":"11","page":"215","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"5","line_end":"6","aya_no":"57","aya_text":"يَٰٓأَيُّهَا ٱلنَّاسُ قَدۡ جَآءَتۡكُم مَّوۡعِظَةٞ مِّن رَّبِّكُمۡ وَشِفَآءٞ لِّمَا فِي ٱلصُّدُورِ وَهُدٗى وَرَحۡمَةٞ لِّلۡمُؤۡمِنِينَ","aya_text_emlaey":"ياأيها الناس قد جاءتكم موعظة من ربكم وشفاء لما في الصدور وهدى ورحمة للمؤمنين","aya_tafseer":"[57] يا أيها الناس قد جاءتكم موعظة من ربكم تذكِّركم عقاب الله وتخوفكم وعيده، وهي القرآن وما اشتمل عليه من الآيات والعظات؛ لإصلاح أخلاقكم وأعمالكم، وفيه دواء لما في القلوب من الجهل والشرك وسائر الأمراض، ورشد لمن اتبعه من الخلق فينجيه من الهلاك، جعله سبحانه وتعالى نعمة ورحمة للمؤمنين، وخصَّهم بذلك؛ لأنهم المنتفعون بالإيمان، وأما الكافرون فهو عليهم عَمَى."},{"id":"1422","jozz":"11","page":"215","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"7","line_end":"8","aya_no":"58","aya_text":"قُلۡ بِفَضۡلِ ٱللَّهِ وَبِرَحۡمَتِهِۦ فَبِذَٰلِكَ فَلۡيَفۡرَحُواْ هُوَ خَيۡرٞ مِّمَّا يَجۡمَعُونَ","aya_text_emlaey":"قل بفضل الله وبرحمته فبذلك فليفرحوا هو خير مما يجمعون","aya_tafseer":"[58] قل -أيها الرسول- لجميع الناس: بفضل الله وبرحمته، وهو ما جاءهم من الله من الهدى ودين الحق وهو الإسلام، فبذلك فليفرحوا؛ فإن الإسلام الذي دعاهم الله إليه، والقرآن الذي أنزله على محمد -صلى الله عليه وسلم-، خير مما يجمعون من حطام الدنيا وما فيها من الزهرة الفانية الذاهبة."},{"id":"1423","jozz":"11","page":"215","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"8","line_end":"10","aya_no":"59","aya_text":"قُلۡ أَرَءَيۡتُم مَّآ أَنزَلَ ٱللَّهُ لَكُم مِّن رِّزۡقٖ فَجَعَلۡتُم مِّنۡهُ حَرَامٗا وَحَلَٰلٗا قُلۡ ءَآللَّهُ أَذِنَ لَكُمۡۖ أَمۡ عَلَى ٱللَّهِ تَفۡتَرُونَ","aya_text_emlaey":"قل أرأيتم ما أنـزل الله لكم من رزق فجعلتم منه حراما وحلالا قل آلله أذن لكم أم على الله تفترون","aya_tafseer":"[59] قل -أيها الرسول- لهؤلاء الجاحدين للوحي: أخبروني عن هذا الرزق الذي خلقه الله لكم من الحيوان والنبات والخيرات فحلَّلتم بعض ذلك لأنفسكم وحرَّمتم بعضه، قل لهم: آلله أذن لكم بذلك، أم تقولون على الله الباطل وتكذبون؟ وإنهم ليقولون على الله الباطل ويكذبون."},{"id":"1424","jozz":"11","page":"215","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"10","line_end":"12","aya_no":"60","aya_text":"وَمَا ظَنُّ ٱلَّذِينَ يَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ يَوۡمَ ٱلۡقِيَٰمَةِۗ إِنَّ ٱللَّهَ لَذُو فَضۡلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَشۡكُرُونَ","aya_text_emlaey":"وما ظن الذين يفترون على الله الكذب يوم القيامة إن الله لذو فضل على الناس ولكن أكثرهم لا يشكرون","aya_tafseer":"[60] وما ظنُّ هؤلاء الذين يتخرصون على الله الكذب يوم الحساب، فيضيفون إليه تحريم ما لم يحرمه عليهم من الأرزاق والأقوات، أن الله فاعل بهم يوم القيامة بكذبهم وفِرْيَتِهم عليه؟ أيحسبون أنه يصفح عنهم ويغفر لهم؟ إن الله لذو فضل على خلقه؛ بتركه معاجلة مَن افترى عليه الكذب بالعقوبة في الدنيا وإمهاله إياه، ولكن أكثر الناس لا يشكرون الله على تفضله عليهم بذلك."},{"id":"1425","jozz":"11","page":"215","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"12","line_end":"15","aya_no":"61","aya_text":"وَمَا تَكُونُ فِي شَأۡنٖ وَمَا تَتۡلُواْ مِنۡهُ مِن قُرۡءَانٖ وَلَا تَعۡمَلُونَ مِنۡ عَمَلٍ إِلَّا كُنَّا عَلَيۡكُمۡ شُهُودًا إِذۡ تُفِيضُونَ فِيهِۚ وَمَا يَعۡزُبُ عَن رَّبِّكَ مِن مِّثۡقَالِ ذَرَّةٖ فِي ٱلۡأَرۡضِ وَلَا فِي ٱلسَّمَآءِ وَلَآ أَصۡغَرَ مِن ذَٰلِكَ وَلَآ أَكۡبَرَ إِلَّا فِي كِتَٰبٖ مُّبِينٍ","aya_text_emlaey":"وما تكون في شأن وما تتلو منه من قرآن ولا تعملون من عمل إلا كنا عليكم شهودا إذ تفيضون فيه وما يعزب عن ربك من مثقال ذرة في الأرض ولا في السماء ولا أصغر من ذلك ولا أكبر إلا في كتاب مبين","aya_tafseer":"[61] وما تكون -أيها الرسول -في أمر مِن أمورك وما تتلو من كتاب الله من آيات، وما يعمل أحد من هذه الأمة عملاً من خير أو شر إلا كنا عليكم شهوداً مُطَّلِعين عليه، إذ تأخذون في ذلك، وتعملونه، فنحفظه عليكم ونجزيكم به، وما يغيب عن علم ربك -أيها الرسول- من زنة نملة صغيرة في الأرض ولا في السماء، ولا أصغر الأشياء ولا أكبرها، إلا في كتاب عند الله واضح جلي، أحاط به علمه وجرى به قلمه."},{"id":"1426","jozz":"11","page":"216","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"1","line_end":"1","aya_no":"62","aya_text":"أَلَآ إِنَّ أَوۡلِيَآءَ ٱللَّهِ لَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ","aya_text_emlaey":"ألا إن أولياء الله لا خوف عليهم ولا هم يحزنون","aya_tafseer":"[62] ألا إن أولياء الله لا خوف عليهم في الآخرة من عقاب الله، ولا هم يحزنون على ما فاتهم من حظوظ الدنيا."},{"id":"1427","jozz":"11","page":"216","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"2","line_end":"2","aya_no":"63","aya_text":"ٱلَّذِينَ ءَامَنُواْ وَكَانُواْ يَتَّقُونَ","aya_text_emlaey":"الذين آمنوا وكانوا يتقون","aya_tafseer":"[63] وصفات هؤلاء الأولياء، أنهم الذين صدَّقوا الله واتبعوا رسوله وما جاء به من عند الله، وكانوا يتقون الله بامتثال أوامره، واجتناب معاصيه."},{"id":"1428","jozz":"11","page":"216","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"2","line_end":"4","aya_no":"64","aya_text":"لَهُمُ ٱلۡبُشۡرَىٰ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَفِي ٱلۡأٓخِرَةِۚ لَا تَبۡدِيلَ لِكَلِمَٰتِ ٱللَّهِۚ ذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ","aya_text_emlaey":"لهم البشرى في الحياة الدنيا وفي الآخرة لا تبديل لكلمات الله ذلك هو الفوز العظيم","aya_tafseer":"[64] لهؤلاء الأولياء البشارة من الله في الحياة الدنيا بما يسرُّهم، ومنها الرؤيا الصالحة يراها المؤمن أو تُرى له، وفي الآخرة بالجنة، لا يخلف الله وعده ولا يغيِّره، ذلك هو الفوز العظيم؛ لأنه اشتمل على النجاة مِن كل محذور، والظَّفَر بكل مطلوب محبوب."},{"id":"1429","jozz":"11","page":"216","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"4","line_end":"5","aya_no":"65","aya_text":"وَلَا يَحۡزُنكَ قَوۡلُهُمۡۘ إِنَّ ٱلۡعِزَّةَ لِلَّهِ جَمِيعًاۚ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ","aya_text_emlaey":"ولا يحزنك قولهم إن العزة لله جميعا هو السميع العليم","aya_tafseer":"[65] ولا يحزنك -أيها الرسول- قولُ المشركين في ربهم وافتراؤهم عليه وإشراكهم معه الأوثان والأصنام؛ فإن الله تعالى هو المتفرد بالقوة الكاملة والقدرة التامة في الدنيا والآخرة، وهو السميع لأقوالهم، العليم بنياتهم وأفعالهم."},{"id":"1430","jozz":"11","page":"216","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"5","line_end":"8","aya_no":"66","aya_text":"أَلَآ إِنَّ لِلَّهِ مَن فِي ٱلسَّمَٰوَٰتِ وَمَن فِي ٱلۡأَرۡضِۗ وَمَا يَتَّبِعُ ٱلَّذِينَ يَدۡعُونَ مِن دُونِ ٱللَّهِ شُرَكَآءَۚ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنۡ هُمۡ إِلَّا يَخۡرُصُونَ","aya_text_emlaey":"ألا إن لله من في السموات ومن في الأرض وما يتبع الذين يدعون من دون الله شركاء إن يتبعون إلا الظن وإن هم إلا يخرصون","aya_tafseer":"[66] ألا إن لله كل مَن في السموات ومَن في الأرض من الملائكة، والإنس، والجن وغير ذلك. وأي شيء يتَّبع مَن يدعو غير الله من الشركاء؟ ما يتَّبعون إلا الشك، وإن هم إلا يكذبون فيما ينسبونه إلى الله."},{"id":"1431","jozz":"11","page":"216","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"8","line_end":"10","aya_no":"67","aya_text":"هُوَ ٱلَّذِي جَعَلَ لَكُمُ ٱلَّيۡلَ لِتَسۡكُنُواْ فِيهِ وَٱلنَّهَارَ مُبۡصِرًاۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَسۡمَعُونَ","aya_text_emlaey":"هو الذي جعل لكم الليل لتسكنوا فيه والنهار مبصرا إن في ذلك لآيات لقوم يسمعون","aya_tafseer":"[67] هو الذي جعل لكم -أيها الناس- الليل لتسكنوا فيه وتهدؤوا من عناء الحركة في طلب المعاش، وجعل لكم النهار؛ لتبصروا فيه، ولتسعَوْا لطلب رزقكم. إن في اختلاف الليل والنهار وحال أهلهما فيهما لَدلالةً وحججاً على أن الله وحده هو المستحق للعبادة، لقوم يسمعون هذه الحجج، ويتفكرون فيها."},{"id":"1432","jozz":"11","page":"216","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"10","line_end":"13","aya_no":"68","aya_text":"قَالُواْ ٱتَّخَذَ ٱللَّهُ وَلَدٗاۗ سُبۡحَٰنَهُۥۖ هُوَ ٱلۡغَنِيُّۖ لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ إِنۡ عِندَكُم مِّن سُلۡطَٰنِۭ بِهَٰذَآۚ أَتَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ","aya_text_emlaey":"قالوا اتخذ الله ولدا سبحانه هو الغني له ما في السموات وما في الأرض إن عندكم من سلطان بهذا أتقولون على الله ما لا تعلمون","aya_tafseer":"[68] قال المشركون: اتخذ الله ولداً، كقولهم: الملائكة بنات الله، أو المسيح ابن الله. تقدَّس الله عن ذلك كله وتنزَّه، هو الغني عن كل ما سواه، له كل ما في السموات والأرض، فكيف يكون له ولد ممن خلق وكل شيء مملوك له؟ وليس لديكم دليل على ما تفترونه من الكذب، أتقولون على الله ما لا تعلمون حقيقته وصحته؟"},{"id":"1433","jozz":"11","page":"216","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"13","line_end":"14","aya_no":"69","aya_text":"قُلۡ إِنَّ ٱلَّذِينَ يَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ لَا يُفۡلِحُونَ","aya_text_emlaey":"قل إن الذين يفترون على الله الكذب لا يفلحون","aya_tafseer":"[69] قل: إن الذين يفترون على الله الكذب باتخاذ الولد وإضافة الشريك إليه، لا ينالون مطلوبهم في الدنيا ولا في الآخرة."},{"id":"1434","jozz":"11","page":"216","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"14","line_end":"15","aya_no":"70","aya_text":"مَتَٰعٞ فِي ٱلدُّنۡيَا ثُمَّ إِلَيۡنَا مَرۡجِعُهُمۡ ثُمَّ نُذِيقُهُمُ ٱلۡعَذَابَ ٱلشَّدِيدَ بِمَا كَانُواْ يَكۡفُرُونَ","aya_text_emlaey":"متاع في الدنيا ثم إلينا مرجعهم ثم نذيقهم العذاب الشديد بما كانوا يكفرون","aya_tafseer":"[70] إنما يتمتعون في الدنيا بكفرهم وكذبهم متاعاً قصيراً، ثم إذا انقضى أجلهم فإلينا مصيرهم، ثم نذيقهم عذاب جهنم؛ بسبب كفرهم بالله وتكذيبهم رسل الله، وجحدهم آياته."},{"id":"1435","jozz":"11","page":"217","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"1","line_end":"4","aya_no":"71","aya_text":"۞ وَٱتۡلُ عَلَيۡهِمۡ نَبَأَ نُوحٍ إِذۡ قَالَ لِقَوۡمِهِۦ يَٰقَوۡمِ إِن كَانَ كَبُرَ عَلَيۡكُم مَّقَامِي وَتَذۡكِيرِي بِـَٔايَٰتِ ٱللَّهِ فَعَلَى ٱللَّهِ تَوَكَّلۡتُ فَأَجۡمِعُوٓاْ أَمۡرَكُمۡ وَشُرَكَآءَكُمۡ ثُمَّ لَا يَكُنۡ أَمۡرُكُمۡ عَلَيۡكُمۡ غُمَّةٗ ثُمَّ ٱقۡضُوٓاْ إِلَيَّ وَلَا تُنظِرُونِ","aya_text_emlaey":"واتل عليهم نبأ نوح إذ قال لقومه ياقوم إن كان كبر عليكم مقامي وتذكيري بآيات الله فعلى الله توكلت فأجمعوا أمركم وشركاءكم ثم لا يكن أمركم عليكم غمة ثم اقضوا إلي ولا تنظرون","aya_tafseer":"[71] واقصص -أيها الرسول- على كفار «مكة» خبر نوح -عليه السلام- مع قومه حين قال لهم: إن كان عَظُمَ عليكم مقامي فيكم وتذكيري إياكم بحجج الله وبراهينه فعلى الله اعتمادي وبه ثقتي، فأعدُّوا أمركم، وادعوا شركاءكم، ثم لا تجعلوا أمركم عليكم مستتراً بل ظاهراً منكشفاً، ثم اقضوا عليَّ بالعقوبة والسوء الذي في إمكانكم، ولا تمهلوني ساعة من نهار."},{"id":"1436","jozz":"11","page":"217","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"4","line_end":"5","aya_no":"72","aya_text":"فَإِن تَوَلَّيۡتُمۡ فَمَا سَأَلۡتُكُم مِّنۡ أَجۡرٍۖ إِنۡ أَجۡرِيَ إِلَّا عَلَى ٱللَّهِۖ وَأُمِرۡتُ أَنۡ أَكُونَ مِنَ ٱلۡمُسۡلِمِينَ","aya_text_emlaey":"فإن توليتم فما سألتكم من أجر إن أجري إلا على الله وأمرت أن أكون من المسلمين","aya_tafseer":"[72] فإن أعرضتم عن دعوتي فإنني لم أسألكم أجراً؛ لأن ثوابي عند ربي وأجري عليه سبحانه، وحده لا شريك له، وأُمرت أن أكون من المنقادين لحكمه."},{"id":"1437","jozz":"11","page":"217","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"6","line_end":"7","aya_no":"73","aya_text":"فَكَذَّبُوهُ فَنَجَّيۡنَٰهُ وَمَن مَّعَهُۥ فِي ٱلۡفُلۡكِ وَجَعَلۡنَٰهُمۡ خَلَٰٓئِفَ وَأَغۡرَقۡنَا ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَاۖ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُنذَرِينَ","aya_text_emlaey":"فكذبوه فنجيناه ومن معه في الفلك وجعلناهم خلائف وأغرقنا الذين كذبوا بآياتنا فانظر كيف كان عاقبة المنذرين","aya_tafseer":"[73] فكذَّب نوحاً قومُه فيما أخبرهم به عن الله، فنجَّيناه هو ومن معه في السفينة، وجعلناهم يَخْلُفون المكذبين في الأرض، وأغرقنا الذين جحدوا حججنا، فتأمَّلْ -أيها الرسول- كيف كان عاقبة القوم الذين أنذرهم رسولهم عذاب الله وبأسه؟"},{"id":"1438","jozz":"11","page":"217","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"8","line_end":"10","aya_no":"74","aya_text":"ثُمَّ بَعَثۡنَا مِنۢ بَعۡدِهِۦ رُسُلًا إِلَىٰ قَوۡمِهِمۡ فَجَآءُوهُم بِٱلۡبَيِّنَٰتِ فَمَا كَانُواْ لِيُؤۡمِنُواْ بِمَا كَذَّبُواْ بِهِۦ مِن قَبۡلُۚ كَذَٰلِكَ نَطۡبَعُ عَلَىٰ قُلُوبِ ٱلۡمُعۡتَدِينَ","aya_text_emlaey":"ثم بعثنا من بعده رسلا إلى قومهم فجاءوهم بالبينات فما كانوا ليؤمنوا بما كذبوا به من قبل كذلك نطبع على قلوب المعتدين","aya_tafseer":"[74] ثم بعثنا من بعد نوح رسلاً إلى أقوامهم (هوداً وصالحاً وإبراهيم ولوطاً وشعيباً وغيرَهم)، فجاء كلُّ رسول قومَه بالمعجزات الدالة على رسالته، وعلى صحة ما دعاهم إليه، فما كانوا ليصدِّقوا ويعملوا بما كذَّب به قوم نوح ومَن سبقهم من الأمم الخالية. وكما ختم الله على قلوب هؤلاء الأقوام فلم يؤمنوا، كذلك يختم على قلوب مَن شابههم ممن بعدهم من الذين تجاوزوا حدود الله، وخالفوا ما دعاهم إليه رسلهم من طاعته؛ عقوبة لهم على معاصيهم."},{"id":"1439","jozz":"11","page":"217","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"10","line_end":"11","aya_no":"75","aya_text":"ثُمَّ بَعَثۡنَا مِنۢ بَعۡدِهِم مُّوسَىٰ وَهَٰرُونَ إِلَىٰ فِرۡعَوۡنَ وَمَلَإِيْهِۦ بِـَٔايَٰتِنَا فَٱسۡتَكۡبَرُواْ وَكَانُواْ قَوۡمٗا مُّجۡرِمِينَ","aya_text_emlaey":"ثم بعثنا من بعدهم موسى وهارون إلى فرعون وملئه بآياتنا فاستكبروا وكانوا قوما مجرمين","aya_tafseer":"[75] ثم بعثنا مِن بعد أولئك الرسل موسى وهارون - عليهما السلام - إلى فرعون وأشراف قومه بالمعجزات الدالة على صدقهما، فاستكبروا عن قَبول الحق، وكانوا قوماً مشركين مجرمين مكذبين."},{"id":"1440","jozz":"11","page":"217","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"12","line_end":"12","aya_no":"76","aya_text":"فَلَمَّا جَآءَهُمُ ٱلۡحَقُّ مِنۡ عِندِنَا قَالُوٓاْ إِنَّ هَٰذَا لَسِحۡرٞ مُّبِينٞ","aya_text_emlaey":"فلما جاءهم الحق من عندنا قالوا إن هذا لسحر مبين","aya_tafseer":"[76] فلما أتى فرعونَ وقومَه المعجزاتُ التي جاء بها موسى قالوا: إن الذي جاء به موسى من الآيات إنما هو سحر ظاهر."},{"id":"1441","jozz":"11","page":"217","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"13","line_end":"14","aya_no":"77","aya_text":"قَالَ مُوسَىٰٓ أَتَقُولُونَ لِلۡحَقِّ لَمَّا جَآءَكُمۡۖ أَسِحۡرٌ هَٰذَا وَلَا يُفۡلِحُ ٱلسَّٰحِرُونَ","aya_text_emlaey":"قال موسى أتقولون للحق لما جاءكم أسحر هذا ولا يفلح الساحرون","aya_tafseer":"[77] قال لهم موسى متعجباً مِن قولهم: أتقولون للحق لما جاءكم: إنه سحر مبين؟ انظروا وَصْفَ ما جاءكم وما اشتمل عليه تجدوه الحق، ولا يفلح الساحرون، ولا يفوزون في الدنيا ولا في الآخرة."},{"id":"1442","jozz":"11","page":"217","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"14","line_end":"15","aya_no":"78","aya_text":"قَالُوٓاْ أَجِئۡتَنَا لِتَلۡفِتَنَا عَمَّا وَجَدۡنَا عَلَيۡهِ ءَابَآءَنَا وَتَكُونَ لَكُمَا ٱلۡكِبۡرِيَآءُ فِي ٱلۡأَرۡضِ وَمَا نَحۡنُ لَكُمَا بِمُؤۡمِنِينَ","aya_text_emlaey":"قالوا أجئتنا لتلفتنا عما وجدنا عليه آباءنا وتكون لكما الكبرياء في الأرض وما نحن لكما بمؤمنين","aya_tafseer":"[78] قال فرعون وملؤه لموسى: أجئتنا لتصْرفنا عما وجدنا عليه آباءنا من عبادة غير الله، وتكون لكما -أنت وهارون- العظمة والسلطان في أرض «مصر»؟ وما نحن لكما بمقرِّين بأنكما رسولان أُرسلتما إلينا؛ لنعبد الله وحده لا شريك له."},{"id":"1443","jozz":"11","page":"218","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"1","line_end":"1","aya_no":"79","aya_text":"وَقَالَ فِرۡعَوۡنُ ٱئۡتُونِي بِكُلِّ سَٰحِرٍ عَلِيمٖ","aya_text_emlaey":"وقال فرعون ائتوني بكل ساحر عليم","aya_tafseer":"[79] وقال فرعون: جيئوني بكل ساحر متقن للسحر."},{"id":"1444","jozz":"11","page":"218","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"1","line_end":"2","aya_no":"80","aya_text":"فَلَمَّا جَآءَ ٱلسَّحَرَةُ قَالَ لَهُم مُّوسَىٰٓ أَلۡقُواْ مَآ أَنتُم مُّلۡقُونَ","aya_text_emlaey":"فلما جاء السحرة قال لهم موسى ألقوا ما أنتم ملقون","aya_tafseer":"[80] فلما جاء السحرة فرعون قال لهم موسى: ألقوا على الأرض ما معكم من حبالكم وعصيِّكم."},{"id":"1445","jozz":"11","page":"218","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"2","line_end":"4","aya_no":"81","aya_text":"فَلَمَّآ أَلۡقَوۡاْ قَالَ مُوسَىٰ مَا جِئۡتُم بِهِ ٱلسِّحۡرُۖ إِنَّ ٱللَّهَ سَيُبۡطِلُهُۥٓ إِنَّ ٱللَّهَ لَا يُصۡلِحُ عَمَلَ ٱلۡمُفۡسِدِينَ","aya_text_emlaey":"فلما ألقوا قال موسى ما جئتم به السحر إن الله سيبطله إن الله لا يصلح عمل المفسدين","aya_tafseer":"[81] فلما ألقَوا حبالهم وعصيَّهم قال لهم موسى: إنَّ الذي جئتم به وألقيتموه هو السحر، إن الله سيُذْهب ما جئتم به وسيُبطله، إن الله لا يصلح عمل مَن سعى في أرض الله بما يكرهه، وأفسد فيها بمعصيته."},{"id":"1446","jozz":"11","page":"218","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"4","line_end":"5","aya_no":"82","aya_text":"وَيُحِقُّ ٱللَّهُ ٱلۡحَقَّ بِكَلِمَٰتِهِۦ وَلَوۡ كَرِهَ ٱلۡمُجۡرِمُونَ","aya_text_emlaey":"ويحق الله الحق بكلماته ولو كره المجرمون","aya_tafseer":"[82] ويثبِّت الله الحق الذي جئتكم به من عنده فيُعليه على باطلكم بكلماته وأمره، ولو كره المجرمون أصحابُ المعاصي مِن آل فرعون."},{"id":"1447","jozz":"11","page":"218","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"5","line_end":"7","aya_no":"83","aya_text":"فَمَآ ءَامَنَ لِمُوسَىٰٓ إِلَّا ذُرِّيَّةٞ مِّن قَوۡمِهِۦ عَلَىٰ خَوۡفٖ مِّن فِرۡعَوۡنَ وَمَلَإِيْهِمۡ أَن يَفۡتِنَهُمۡۚ وَإِنَّ فِرۡعَوۡنَ لَعَالٖ فِي ٱلۡأَرۡضِ وَإِنَّهُۥ لَمِنَ ٱلۡمُسۡرِفِينَ","aya_text_emlaey":"فما آمن لموسى إلا ذرية من قومه على خوف من فرعون وملئهم أن يفتنهم وإن فرعون لعال في الأرض وإنه لمن المسرفين","aya_tafseer":"[83] فما آمن لموسى عليه السلام -مع ما أتاهم به من الحجج والأدلة- إلا ذرية من قومه من بني إسرائيل، وهم خائفون من فرعون وملئه أن يفتنوهم بالعذاب، فيصدُّوهم عن دينهم، وإن فرعون لَجبار مستكبر في الأرض، وإنه لمن المتجاوزين الحد في الكفر والفساد."},{"id":"1448","jozz":"11","page":"218","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"7","line_end":"8","aya_no":"84","aya_text":"وَقَالَ مُوسَىٰ يَٰقَوۡمِ إِن كُنتُمۡ ءَامَنتُم بِٱللَّهِ فَعَلَيۡهِ تَوَكَّلُوٓاْ إِن كُنتُم مُّسۡلِمِينَ","aya_text_emlaey":"وقال موسى ياقوم إن كنتم آمنتم بالله فعليه توكلوا إن كنتم مسلمين","aya_tafseer":"[84] وقال موسى: يا قومي إن صدقتم بالله -جلَّ وعلا- وامتثلتم شرعه فثقوا به، وسلِّموا لأمره، وعلى الله توكلوا إن كنتم مذعنين له بالطاعة."},{"id":"1449","jozz":"11","page":"218","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"9","line_end":"9","aya_no":"85","aya_text":"فَقَالُواْ عَلَى ٱللَّهِ تَوَكَّلۡنَا رَبَّنَا لَا تَجۡعَلۡنَا فِتۡنَةٗ لِّلۡقَوۡمِ ٱلظَّٰلِمِينَ","aya_text_emlaey":"فقالوا على الله توكلنا ربنا لا تجعلنا فتنة للقوم الظالمين","aya_tafseer":"[85] فقال قوم موسى له: على الله وحده لا شريك له اعتمدنا، وإليه فوَّضنا أمرنا، ربنا لا تنصرهم علينا فيكون ذلك فتنة لنا عن الدين، أو يُفتن الكفارُ بنصرهم، فيقولوا: لو كانوا على حق لما غُلبوا."},{"id":"1450","jozz":"11","page":"218","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"10","line_end":"10","aya_no":"86","aya_text":"وَنَجِّنَا بِرَحۡمَتِكَ مِنَ ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ","aya_text_emlaey":"ونجنا برحمتك من القوم الكافرين","aya_tafseer":"[86] ونجِّنا برحمتك من القوم الكافرين فرعون وملئه؛ لأنهم كانوا يأخذونهم بالأعمال الشاقة."},{"id":"1451","jozz":"11","page":"218","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"10","line_end":"12","aya_no":"87","aya_text":"وَأَوۡحَيۡنَآ إِلَىٰ مُوسَىٰ وَأَخِيهِ أَن تَبَوَّءَا لِقَوۡمِكُمَا بِمِصۡرَ بُيُوتٗا وَٱجۡعَلُواْ بُيُوتَكُمۡ قِبۡلَةٗ وَأَقِيمُواْ ٱلصَّلَوٰةَۗ وَبَشِّرِ ٱلۡمُؤۡمِنِينَ","aya_text_emlaey":"وأوحينا إلى موسى وأخيه أن تبوآ لقومكما بمصر بيوتا واجعلوا بيوتكم قبلة وأقيموا الصلاة وبشر المؤمنين","aya_tafseer":"[87] وأوحينا إلى موسى وأخيه هارون أن اتخذا لقومكما بيوتاً في «مصر» تكون مساكن وملاجئ تعتصمون بها، واجعلوا بيوتكم أماكن تصلُّون فيها عند الخوف، وأدُّوا الصلاة المفروضة في أوقاتها. وبشِّر المؤمنين المطيعين لله بالنصر المؤزر، والثواب الجزيل منه سبحانه وتعالى."},{"id":"1452","jozz":"11","page":"218","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"12","line_end":"15","aya_no":"88","aya_text":"وَقَالَ مُوسَىٰ رَبَّنَآ إِنَّكَ ءَاتَيۡتَ فِرۡعَوۡنَ وَمَلَأَهُۥ زِينَةٗ وَأَمۡوَٰلٗا فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا رَبَّنَا لِيُضِلُّواْ عَن سَبِيلِكَۖ رَبَّنَا ٱطۡمِسۡ عَلَىٰٓ أَمۡوَٰلِهِمۡ وَٱشۡدُدۡ عَلَىٰ قُلُوبِهِمۡ فَلَا يُؤۡمِنُواْ حَتَّىٰ يَرَوُاْ ٱلۡعَذَابَ ٱلۡأَلِيمَ","aya_text_emlaey":"وقال موسى ربنا إنك آتيت فرعون وملأه زينة وأموالا في الحياة الدنيا ربنا ليضلوا عن سبيلك ربنا اطمس على أموالهم واشدد على قلوبهم فلا يؤمنوا حتى يروا العذاب الأليم","aya_tafseer":"[88] وقال موسى: ربنا إنك أعطيت فرعون وأشراف قومه زينة من متاع الدنيا، فلم يشكروا لك؛ وإنما استعانوا بها على الإضلال عن سبيلك، ربنا اطمس على أموالهم، فلا ينتفعوا بها، واختم على قلوبهم حتى لا تنشرح للإيمان، فلا يؤمنوا حتى يروا العذاب الشديد الموجع."},{"id":"1453","jozz":"11","page":"219","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"1","line_end":"2","aya_no":"89","aya_text":"قَالَ قَدۡ أُجِيبَت دَّعۡوَتُكُمَا فَٱسۡتَقِيمَا وَلَا تَتَّبِعَآنِّ سَبِيلَ ٱلَّذِينَ لَا يَعۡلَمُونَ","aya_text_emlaey":"قال قد أجيبت دعوتكما فاستقيما ولا تتبعان سبيل الذين لا يعلمون","aya_tafseer":"[89] قال الله تعالى لهما: قد أجيبت دعوتكما في فرعون وملئه وأموالهم -وكان موسى يدعو، وهارون يؤمِّن على دعائه، فمن هنا نسبت الدعوة إلى الاثنين- فاستقيما على دينكما، واستمِرَّا على دعوتكما فرعون وقومه إلى توحيد الله وطاعته، ولا تسلكا طريق مَن لا يعلم حقيقة وعدي ووعيدي."},{"id":"1454","jozz":"11","page":"219","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"2","line_end":"5","aya_no":"90","aya_text":"۞ وَجَٰوَزۡنَا بِبَنِيٓ إِسۡرَٰٓءِيلَ ٱلۡبَحۡرَ فَأَتۡبَعَهُمۡ فِرۡعَوۡنُ وَجُنُودُهُۥ بَغۡيٗا وَعَدۡوًاۖ حَتَّىٰٓ إِذَآ أَدۡرَكَهُ ٱلۡغَرَقُ قَالَ ءَامَنتُ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا ٱلَّذِيٓ ءَامَنَتۡ بِهِۦ بَنُوٓاْ إِسۡرَٰٓءِيلَ وَأَنَا۠ مِنَ ٱلۡمُسۡلِمِينَ","aya_text_emlaey":"وجاوزنا ببني إسرائيل البحر فأتبعهم فرعون وجنوده بغيا وعدوا حتى إذا أدركه الغرق قال آمنت أنه لا إله إلا الذي آمنت به بنو إسرائيل وأنا من المسلمين","aya_tafseer":"[90] وقطَعْنا ببني إسرائيل البحر حتى جاوزوه، فأتبعهم فرعون وجنوده ظلماً وعدواناً، فسلكوا البحر وراءهم، حتى إذا أحاط بفرعون الغرق قال: آمنتُ أنه لا إله إلا الذي آمنتْ به بنو إسرائيل، وأنا من الموحدين المستسلمين بالانقياد والطاعة."},{"id":"1455","jozz":"11","page":"219","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"5","line_end":"6","aya_no":"91","aya_text":"ءَآلۡـَٰٔنَ وَقَدۡ عَصَيۡتَ قَبۡلُ وَكُنتَ مِنَ ٱلۡمُفۡسِدِينَ","aya_text_emlaey":"آلآن وقد عصيت قبل وكنت من المفسدين","aya_tafseer":"[91] آلآن يا فرعون، وقد نزل بك الموت تقرُّ لله بالعبودية، وقد عصيته قبل نزول عذابه بك، وكنت من المفسدين الصادين عن سبيله! فلا تنفعك التوبة ساعة الاحتضار ومشاهدة الموت والعذاب."},{"id":"1456","jozz":"11","page":"219","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"6","line_end":"7","aya_no":"92","aya_text":"فَٱلۡيَوۡمَ نُنَجِّيكَ بِبَدَنِكَ لِتَكُونَ لِمَنۡ خَلۡفَكَ ءَايَةٗۚ وَإِنَّ كَثِيرٗا مِّنَ ٱلنَّاسِ عَنۡ ءَايَٰتِنَا لَغَٰفِلُونَ","aya_text_emlaey":"فاليوم ننجيك ببدنك لتكون لمن خلفك آية وإن كثيرا من الناس عن آياتنا لغافلون","aya_tafseer":"[92] فاليوم نجعلك على مرتفع من الأرض ببدنك، ينظر إليك من كذَّب بهلاكك؛ لتكون لمن بعدك من الناس عبرة يعتبرون بك. وإن كثيراً من الناس عن حججنا وأدلتنا لَغافلون، لا يتفكرون فيها ولا يعتبرون."},{"id":"1457","jozz":"11","page":"219","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"8","line_end":"10","aya_no":"93","aya_text":"وَلَقَدۡ بَوَّأۡنَا بَنِيٓ إِسۡرَٰٓءِيلَ مُبَوَّأَ صِدۡقٖ وَرَزَقۡنَٰهُم مِّنَ ٱلطَّيِّبَٰتِ فَمَا ٱخۡتَلَفُواْ حَتَّىٰ جَآءَهُمُ ٱلۡعِلۡمُۚ إِنَّ رَبَّكَ يَقۡضِي بَيۡنَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ فِيمَا كَانُواْ فِيهِ يَخۡتَلِفُونَ","aya_text_emlaey":"ولقد بوأنا بني إسرائيل مبوأ صدق ورزقناهم من الطيبات فما اختلفوا حتى جاءهم العلم إن ربك يقضي بينهم يوم القيامة فيما كانوا فيه يختلفون","aya_tafseer":"[93] ولقد أنزلنا بني إسرائيل منزلاً صالحاً مختاراً في بلاد «الشام» و «مصر»، ورزقناهم الرزق الحلال الطيب من خيرات الأرض المباركة، فما اختلفوا في أمر دينهم إلا مِن بعد ما جاءهم العلم الموجب لاجتماعهم وأْتِلَافهم، ومن ذلك ما اشتملت عليه التوراة من الإخبار بنبوة محمد -صلى الله عليه وسلم-. إن ربك -أيها الرسول- يقضي بينهم يوم القيامة، ويَفْصِل فيما كانوا يختلفون فيه من أمرك، فيدخل المكذبين النار والمؤمنين الجنة."},{"id":"1458","jozz":"11","page":"219","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"10","line_end":"12","aya_no":"94","aya_text":"فَإِن كُنتَ فِي شَكّٖ مِّمَّآ أَنزَلۡنَآ إِلَيۡكَ فَسۡـَٔلِ ٱلَّذِينَ يَقۡرَءُونَ ٱلۡكِتَٰبَ مِن قَبۡلِكَۚ لَقَدۡ جَآءَكَ ٱلۡحَقُّ مِن رَّبِّكَ فَلَا تَكُونَنَّ مِنَ ٱلۡمُمۡتَرِينَ","aya_text_emlaey":"فإن كنت في شك مما أنـزلنا إليك فاسأل الذين يقرؤون الكتاب من قبلك لقد جاءك الحق من ربك فلا تكونن من الممترين","aya_tafseer":"[94] فإن كنت -أيها الرسول- في ريب من حقيقة ما أخبرناك به فاسأل الذين يقرؤون الكتاب من قبلك، من أهل التوراة والإنجيل سؤالَ تقرير وإشهاد، فإن ذلك ثابت في كتبهم، لقد جاءك الحق اليقين من ربك بأنك رسول الله، وأن هؤلاء اليهود والنصارى يعلمون صحة ذلك، ويجدون صفتك في كتبهم، ولكنهم ينكرون ذلك مع علمهم به، فلا تكوننَّ من الشاكين في صحة ذلك وحقيقته. والمقصود من الآية إقامة الحجة على المشركين بشهادة أهل الكتاب من اليهود والنصارى؛ قطعاً لمعذرتهم."},{"id":"1459","jozz":"11","page":"219","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"13","line_end":"13","aya_no":"95","aya_text":"وَلَا تَكُونَنَّ مِنَ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِ ٱللَّهِ فَتَكُونَ مِنَ ٱلۡخَٰسِرِينَ","aya_text_emlaey":"ولا تكونن من الذين كذبوا بآيات الله فتكون من الخاسرين","aya_tafseer":"[95] ولا تكونن -أيها الرسول- من الذين كذَّبوا بحجج الله وأدلته فتكون من الخاسرين الذين سخِطَ الله عليهم ونالوا عقابه."},{"id":"1460","jozz":"11","page":"219","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"14","line_end":"14","aya_no":"96","aya_text":"إِنَّ ٱلَّذِينَ حَقَّتۡ عَلَيۡهِمۡ كَلِمَتُ رَبِّكَ لَا يُؤۡمِنُونَ","aya_text_emlaey":"إن الذين حقت عليهم كلمت ربك لا يؤمنون","aya_tafseer":"[96] إن الذين حقَّت عليهم كلمة ربك -أيها الرسول- بطردهم من رحمته وعذابه لهم، لا يؤمنون بحجج الله، ولا يقرُّون بوحدانيته، ولا يعملون بشرعه."},{"id":"1461","jozz":"11","page":"219","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"15","line_end":"15","aya_no":"97","aya_text":"وَلَوۡ جَآءَتۡهُمۡ كُلُّ ءَايَةٍ حَتَّىٰ يَرَوُاْ ٱلۡعَذَابَ ٱلۡأَلِيمَ","aya_text_emlaey":"ولو جاءتهم كل آية حتى يروا العذاب الأليم","aya_tafseer":"[97] ولو جاءتهم كل موعظة وعبرة حتى يعاينوا العذاب الموجع، فحينئذ يؤمنون، ولا ينفعهم إيمانهم."},{"id":"1462","jozz":"11","page":"220","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"1","line_end":"3","aya_no":"98","aya_text":"فَلَوۡلَا كَانَتۡ قَرۡيَةٌ ءَامَنَتۡ فَنَفَعَهَآ إِيمَٰنُهَآ إِلَّا قَوۡمَ يُونُسَ لَمَّآ ءَامَنُواْ كَشَفۡنَا عَنۡهُمۡ عَذَابَ ٱلۡخِزۡيِ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَمَتَّعۡنَٰهُمۡ إِلَىٰ حِينٖ","aya_text_emlaey":"فلولا كانت قرية آمنت فنفعها إيمانها إلا قوم يونس لما آمنوا كشفنا عنهم عذاب الخزي في الحياة الدنيا ومتعناهم إلى حين","aya_tafseer":"[98] لم ينفع الإيمانُ أهلَ قرية آمنوا عند معاينة العذاب إلا أهل قرية يونس بن مَتَّى، فإنهم لَمَّا أيقنوا أن العذاب نازل بهم تابوا إلى الله تعالى توبة نصوحاً، فلمَّا تبيَّن منهم الصدق في توبتهم كشف الله عنهم عذاب الخزي بعد أن اقترب منهم، وتركهم في الدنيا يستمتعون إلى وقت إنهاء آجالهم."},{"id":"1463","jozz":"11","page":"220","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"3","line_end":"4","aya_no":"99","aya_text":"وَلَوۡ شَآءَ رَبُّكَ لَأٓمَنَ مَن فِي ٱلۡأَرۡضِ كُلُّهُمۡ جَمِيعًاۚ أَفَأَنتَ تُكۡرِهُ ٱلنَّاسَ حَتَّىٰ يَكُونُواْ مُؤۡمِنِينَ","aya_text_emlaey":"ولو شاء ربك لآمن من في الأرض كلهم جميعا أفأنت تكره الناس حتى يكونوا مؤمنين","aya_tafseer":"[99] ولو شاء ربك -أيها الرسول- الإيمان لأهل الأرض كلهم لآمنوا جميعاً بما جئتهم به، ولكن له حكمة في ذلك؛ فإنه يهدي من يشاء ويضل من يشاء وَفْق حكمته، وليس في استطاعتك أن تُكْره الناس على الإيمان."},{"id":"1464","jozz":"11","page":"220","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"5","line_end":"6","aya_no":"100","aya_text":"وَمَا كَانَ لِنَفۡسٍ أَن تُؤۡمِنَ إِلَّا بِإِذۡنِ ٱللَّهِۚ وَيَجۡعَلُ ٱلرِّجۡسَ عَلَى ٱلَّذِينَ لَا يَعۡقِلُونَ","aya_text_emlaey":"وما كان لنفس أن تؤمن إلا بإذن الله ويجعل الرجس على الذين لا يعقلون","aya_tafseer":"[100] وما كان لنفس أن تؤمن بالله إلا بإذنه وتوفيقه، فلا تُجهد نفسك في ذلك، فإن أمرهم إلى الله. ويجعل الله العذاب والخزي على الذين لا يعقلون أمره ونهيه."},{"id":"1465","jozz":"11","page":"220","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"6","line_end":"7","aya_no":"101","aya_text":"قُلِ ٱنظُرُواْ مَاذَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَمَا تُغۡنِي ٱلۡأٓيَٰتُ وَٱلنُّذُرُ عَن قَوۡمٖ لَّا يُؤۡمِنُونَ","aya_text_emlaey":"قل انظروا ماذا في السموات والأرض وما تغني الآيات والنذر عن قوم لا يؤمنون","aya_tafseer":"[101] قل -أيها الرسول- لقومك: تفكروا واعتبروا بما في السموات والأرض من آيات الله البينات، ولكن الآياتُ والعبر والرسلُ المنذرةُ عبادَ الله عقابه، لا تنفع قوماً لا يؤمنون بشيء من ذلك؛ لإعراضهم وعنادهم."},{"id":"1466","jozz":"11","page":"220","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"8","line_end":"9","aya_no":"102","aya_text":"فَهَلۡ يَنتَظِرُونَ إِلَّا مِثۡلَ أَيَّامِ ٱلَّذِينَ خَلَوۡاْ مِن قَبۡلِهِمۡۚ قُلۡ فَٱنتَظِرُوٓاْ إِنِّي مَعَكُم مِّنَ ٱلۡمُنتَظِرِينَ","aya_text_emlaey":"فهل ينتظرون إلا مثل أيام الذين خلوا من قبلهم قل فانتظروا إني معكم من المنتظرين","aya_tafseer":"[102] فهل ينتظر هؤلاء إلا يوماً يعاينون فيه عذاب الله مثل أيام أسلافهم المكذبين الذين مَضَوا قبلهم؟ قل لهم -أيها الرسول-: فانتظروا عقاب الله إني معكم من المنتظرين عقابكم."},{"id":"1467","jozz":"11","page":"220","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"9","line_end":"10","aya_no":"103","aya_text":"ثُمَّ نُنَجِّي رُسُلَنَا وَٱلَّذِينَ ءَامَنُواْۚ كَذَٰلِكَ حَقًّا عَلَيۡنَا نُنجِ ٱلۡمُؤۡمِنِينَ","aya_text_emlaey":"ثم ننجي رسلنا والذين آمنوا كذلك حقا علينا ننج المؤمنين","aya_tafseer":"[103] ثم ننجِّي رسلنا والذين آمنوا معهم، وكما نجينا أولئك ننجِّيك -أيها الرسول- ومَن آمن بك تفضلاً منَّا ورحمة."},{"id":"1468","jozz":"11","page":"220","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"11","line_end":"13","aya_no":"104","aya_text":"قُلۡ يَٰٓأَيُّهَا ٱلنَّاسُ إِن كُنتُمۡ فِي شَكّٖ مِّن دِينِي فَلَآ أَعۡبُدُ ٱلَّذِينَ تَعۡبُدُونَ مِن دُونِ ٱللَّهِ وَلَٰكِنۡ أَعۡبُدُ ٱللَّهَ ٱلَّذِي يَتَوَفَّىٰكُمۡۖ وَأُمِرۡتُ أَنۡ أَكُونَ مِنَ ٱلۡمُؤۡمِنِينَ","aya_text_emlaey":"قل ياأيها الناس إن كنتم في شك من ديني فلا أعبد الذين تعبدون من دون الله ولكن أعبد الله الذي يتوفاكم وأمرت أن أكون من المؤمنين","aya_tafseer":"[104] قل -أيها الرسول- لهؤلاء الناس: إن كنتم في شك من صحة ديني الذي دعوتكم إليه، وهو الإسلام، ومن ثباتي واستقامتي عليه، وترجون تحويلي عنه، فإني لا أعبد -في حال من الأحوال- أحداً من الذين تعبدونهم مما اتخذتم من الأصنام والأوثان، ولكن أعبد الله وحده الذي يميتكم ويقبض أرواحكم، وأُمِرت أن أكون من المصدِّقين به العاملين بشرعه."},{"id":"1469","jozz":"11","page":"220","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"13","line_end":"14","aya_no":"105","aya_text":"وَأَنۡ أَقِمۡ وَجۡهَكَ لِلدِّينِ حَنِيفٗا وَلَا تَكُونَنَّ مِنَ ٱلۡمُشۡرِكِينَ","aya_text_emlaey":"وأن أقم وجهك للدين حنيفا ولا تكونن من المشركين","aya_tafseer":"[105] وأن أقم -أيها الرسول- نفسك على دين الإسلام مستقيماً عليه، غير مائل عنه إلى يهودية ولا نصرانية ولا عبادة غيره، ولا تكونن ممن يشرك في عبادة ربه الآلهة والأنداد، فتكون من الهالكين. وهذا وإن كان خطاباً للرسول -صلى الله عليه وسلم- فإنه موجَّه لعموم الأمة."},{"id":"1470","jozz":"11","page":"220","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"14","line_end":"15","aya_no":"106","aya_text":"وَلَا تَدۡعُ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُكَ وَلَا يَضُرُّكَۖ فَإِن فَعَلۡتَ فَإِنَّكَ إِذٗا مِّنَ ٱلظَّٰلِمِينَ","aya_text_emlaey":"ولا تدع من دون الله ما لا ينفعك ولا يضرك فإن فعلت فإنك إذا من الظالمين","aya_tafseer":"[106] ولا تَدْعُ -أيها الرسول- من دون الله شيئاً من الأوثان والأصنام؛ لأنها لا تنفع ولا تضرُّ، فإن فعلْتَ ذلك ودعوتها من دون الله فإنك إذاً من المشركين بالله، الظالمين لأنفسهم بالشرك والمعصية. وهذا وإن كان خطاباً للرسول -صلى الله عليه وسلم- فإنه موجَّه لعموم الأمة."},{"id":"1471","jozz":"11","page":"221","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"1","line_end":"3","aya_no":"107","aya_text":"وَإِن يَمۡسَسۡكَ ٱللَّهُ بِضُرّٖ فَلَا كَاشِفَ لَهُۥٓ إِلَّا هُوَۖ وَإِن يُرِدۡكَ بِخَيۡرٖ فَلَا رَآدَّ لِفَضۡلِهِۦۚ يُصِيبُ بِهِۦ مَن يَشَآءُ مِنۡ عِبَادِهِۦۚ وَهُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ","aya_text_emlaey":"وإن يمسسك الله بضر فلا كاشف له إلا هو وإن يردك بخير فلا راد لفضله يصيب به من يشاء من عباده وهو الغفور الرحيم","aya_tafseer":"[107] وإن يصبك الله -أيها الرسول- بشدة أو بلاء فلا كاشف لذلك إلا هو جلَّ وعلا، وإن يُرِدْك برخاء أو نعمة لا يمنعه عنك أحد، يصيب الله عز وجل بالسراء والضراء من يشاء من عباده، وهو الغفور لذنوب مَن تاب، الرحيم بمن آمن به وأطاعه."},{"id":"1472","jozz":"11","page":"221","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"3","line_end":"5","aya_no":"108","aya_text":"قُلۡ يَٰٓأَيُّهَا ٱلنَّاسُ قَدۡ جَآءَكُمُ ٱلۡحَقُّ مِن رَّبِّكُمۡۖ فَمَنِ ٱهۡتَدَىٰ فَإِنَّمَا يَهۡتَدِي لِنَفۡسِهِۦۖ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيۡهَاۖ وَمَآ أَنَا۠ عَلَيۡكُم بِوَكِيلٖ","aya_text_emlaey":"قل ياأيها الناس قد جاءكم الحق من ربكم فمن اهتدى فإنما يهتدي لنفسه ومن ضل فإنما يضل عليها وما أنا عليكم بوكيل","aya_tafseer":"[108] قل -أيها الرسول- لهؤلاء الناس: قد جاءكم رسول الله بالقرآن الذي فيه بيان هدايتكم، فمن اهتدى بهدي الله فإنما ثمرة عمله راجعة إليه، ومن انحرف عن الحق وأصرَّ على الضلال فإنما ضلاله وضرره على نفسه، وما أنا موكَّل بكم حتى تكونوا مؤمنين، إنما أنا رسول مبلِّغ أبلِّغكم ما أُرسِلت به."},{"id":"1473","jozz":"11","page":"221","sura_no":"10","sura_name_en":"Yūnus","sura_name_ar":"يُونس ","line_start":"5","line_end":"6","aya_no":"109","aya_text":"وَٱتَّبِعۡ مَا يُوحَىٰٓ إِلَيۡكَ وَٱصۡبِرۡ حَتَّىٰ يَحۡكُمَ ٱللَّهُۚ وَهُوَ خَيۡرُ ٱلۡحَٰكِمِينَ","aya_text_emlaey":"واتبع ما يوحى إليك واصبر حتى يحكم الله وهو خير الحاكمين","aya_tafseer":"[109] واتبع -أيها الرسول- وحي الله الذي يوحيه إليك فاعمل به، واصبر على طاعة الله تعالى، وعن معصيته، وعلى أذى من آذاك في تبليغ رسالته، حتى يقضي الله فيهم وفيك أمره، وهو -عزَّ وجل- خير الحاكمين؛ فإن حكمه مشتمل على العدل التام."}]
